ui/editorial-button.code:
"use client";

import type {
  AnchorHTMLAttributes,
  ButtonHTMLAttributes,
  ReactNode,
} from "react";
import styles from "./styles.module.css";

export type EditorialButtonVariant =
  | "solid"
  | "dark"
  | "ghost"
  | "light"
  | "outline"
  | "accent";

export type EditorialButtonSize = "sm" | "md" | "lg";

interface EditorialButtonBaseProps {
  variant?: EditorialButtonVariant;
  size?: EditorialButtonSize;
  blend?: boolean;
  trailingArrow?: boolean;
  className?: string;
  children: ReactNode;
}

export type EditorialButtonProps =
  | (EditorialButtonBaseProps & {
      as?: "button";
      href?: undefined;
    } & ButtonHTMLAttributes<HTMLButtonElement>)
  | (EditorialButtonBaseProps & {
      as?: "a";
      href: string;
    } & AnchorHTMLAttributes<HTMLAnchorElement>);

const VARIANT_CLASS: Record<EditorialButtonVariant, string> = {
  solid: styles.solid,
  dark: styles.dark,
  ghost: styles.ghost,
  outline: styles.ghost,
  light: styles.light,
  accent: styles.accent,
};

const SIZE_CLASS: Record<EditorialButtonSize, string> = {
  sm: styles.sizeSm,
  md: "",
  lg: styles.sizeLg,
};

export function EditorialButton(props: EditorialButtonProps) {
  const {
    variant = "solid",
    size = "md",
    blend = false,
    trailingArrow = false,
    className = "",
    children,
  } = props;

  const classes = [
    styles.btn,
    VARIANT_CLASS[variant],
    SIZE_CLASS[size],
    blend ? styles.blend : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  const content = trailingArrow ? (
    <>
      <span>{children}</span>
      <span aria-hidden="true" className={styles.arrow}>
        →
      </span>
    </>
  ) : (
    children
  );

  if (props.as === "a" || typeof props.href === "string") {
    const {
      as: _as,
      variant: _variant,
      size: _size,
      blend: _blend,
      trailingArrow: _trailingArrow,
      className: _className,
      children: _children,
      ...anchorProps
    } = props as EditorialButtonBaseProps & {
      as?: "a";
      href: string;
    } & AnchorHTMLAttributes<HTMLAnchorElement>;

    return (
      <a className={classes} {...anchorProps}>
        {content}
      </a>
    );
  }

  const {
    as: _as,
    href: _href,
    variant: _variant,
    size: _size,
    blend: _blend,
    trailingArrow: _trailingArrow,
    className: _className,
    children: _children,
    type = "button",
    ...buttonProps
  } = props as EditorialButtonBaseProps & {
    as?: "button";
    href?: undefined;
  } & ButtonHTMLAttributes<HTMLButtonElement>;

  return (
    <button type={type} className={classes} {...buttonProps}>
      {content}
    </button>
  );
}

ui/editorial-button.stylesCss:
.btn {
  position: relative;
  display: inline-block;
  padding: 5px;
  border: 0;
  border-radius: 3px;
  font-family: var(--rk-font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: normal;
  text-transform: uppercase;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  box-sizing: border-box;
  transition-property: background-color, color, border-color;
  transition-duration: 0.6s;
  transition-timing-function: var(--rk-ease, cubic-bezier(0.215, 0.61, 0.355, 1));
}

.btn:focus-visible {
  outline: 2px solid var(--rk-accent);
  outline-offset: 2px;
}

.btn:disabled,
.btn[aria-disabled="true"] {
  opacity: 0.4;
  pointer-events: none;
  cursor: default;
}

.solid,
.dark {
  background-color: var(--rk-fg);
  color: var(--rk-bg);
  border: 0;
}

.solid:not(:disabled):not([aria-disabled="true"]):hover,
.solid:not(:disabled):not([aria-disabled="true"]):active,
.dark:not(:disabled):not([aria-disabled="true"]):hover,
.dark:not(:disabled):not([aria-disabled="true"]):active {
  background-color: var(--rk-surface-elevated);
  color: var(--rk-fg);
  border-color: transparent;
}

.ghost {
  background-color: transparent;
  color: var(--rk-fg);
  border: 1.25px solid var(--rk-fg);
}

.ghost:not(:disabled):not([aria-disabled="true"]):hover,
.ghost:not(:disabled):not([aria-disabled="true"]):active {
  background-color: var(--rk-fg);
  color: var(--rk-bg);
  border-color: var(--rk-fg);
}

.light {
  background-color: var(--rk-bg);
  color: var(--rk-fg);
  border: 0;
}

.light:not(:disabled):not([aria-disabled="true"]):hover,
.light:not(:disabled):not([aria-disabled="true"]):active {
  background-color: var(--rk-fg);
  color: var(--rk-bg);
}

.accent {
  background-color: var(--rk-accent);
  color: var(--rk-accent-fg);
  border: 0;
}

.accent:not(:disabled):not([aria-disabled="true"]):hover,
.accent:not(:disabled):not([aria-disabled="true"]):active {
  background-color: var(--rk-fg);
  color: var(--rk-bg);
}

.blend {
  mix-blend-mode: lighten;
}

.blend:not(:disabled):not([aria-disabled="true"]):hover,
.blend:not(:disabled):not([aria-disabled="true"]):active,
.blend:not(:disabled):not([aria-disabled="true"]):focus-visible {
  mix-blend-mode: revert;
}

.sizeSm {
  padding: 4px 6px;
  font-size: 16px;
}

.sizeLg {
  padding: 8px 12px;
  font-size: 26px;
}

.arrow {
  display: inline-block;
  margin-left: 0.3em;
  transition: transform 0.3s var(--rk-ease, cubic-bezier(0.215, 0.61, 0.355, 1));
}

.btn:not(:disabled):not([aria-disabled="true"]):hover .arrow {
  transform: translateX(3px);
}

@media only screen and (min-width: 1024px) {
