    padding: min(0.347222vw, 0.617284vh);
    font-size: min(1.80556vw, 3.20988vh);
  }

  .sizeSm {
    padding: min(0.25vw, 0.444444vh) min(0.416667vw, 0.740741vh);
    font-size: min(1.25vw, 2.22222vh);
  }

  .sizeLg {
    padding: min(0.555556vw, 0.987654vh) min(0.833333vw, 1.48148vh);
    font-size: min(2.22222vw, 3.95062vh);
