  margin: 0 0 0 auto;
  font-family: var(--rk-font-body);
  font-size: 16px;
  font-weight: 300;
  line-height: 1.35;
}

.specTable {
  display: table;
  width: 100%;
  margin-top: auto;
  border-collapse: collapse;
  font-family: var(--rk-font-narrow, var(--rk-font-display));
  font-size: 15px;
  font-weight: 300;
  line-height: 1;
  letter-spacing: normal;
  text-transform: uppercase;
}
.specRow {
  display: grid;
  grid-template-columns: 70px auto;
  column-gap: 20px;
}
.specRow + .specRow {
  margin-top: 5px;
}
.specLabel {
  padding: 0;
  font-weight: 300;
}
.specValue {
  padding: 0;
  font-weight: 700;
}

.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  aspect-ratio: 423 / 525;
  overflow: hidden;
  border-radius: var(--rk-radius-md, 4px);
  background-color: var(--rk-surface);
  color: var(--rk-fg);
  font-family: var(--rk-font-body);
  font-size: 16px;
  font-weight: 300;
  line-height: 1;
}

.tileLink {
  position: relative;
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 24px 20px;
  color: inherit;
  text-decoration: none;
}

.tileImg,
.tileFallback {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(1) translateZ(0);
  transition: transform 0.5s cubic-bezier(0.645, 0.045, 0.355, 1);
}
.tileImg {
  width: 80%;
  height: auto;
}
.tileFallback {
  width: 62%;
  aspect-ratio: 3 / 4;
  border-radius: var(--rk-radius-sm, 2px);
  border: 1px solid var(--rk-border-strong);
  background: color-mix(in srgb, var(--rk-bg) 82%, var(--rk-surface));
}

.tileInfos {
  position: relative;
  display: flex;
  width: 100%;
  align-items: flex-end;
  justify-content: space-between;
  column-gap: 20px;
  margin-top: auto;
}
.tileTitle {
  margin: 0;
  font-family: var(--rk-font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
}

.tileHover {
  position: absolute;
  inset: 24px 20px;
  z-index: 1;
  display: flex;
  flex-direction: column;
  padding: 20px;
  border-radius: var(--rk-radius-md, 4px);
  background-color: var(--rk-fg);
  color: var(--rk-bg);
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.3s cubic-bezier(0.215, 0.61, 0.355, 1), visibility 0s linear 0.3s;
}
.tileHover p {
  margin: 0 0 16px;
  line-height: 1;
}
.tile:hover .tileHover,
.tile:focus-within .tileHover {
  visibility: visible;
  opacity: 1;
  transition: opacity 0.4s cubic-bezier(0.215, 0.61, 0.355, 1) 0.2s, visibility 0s linear;
}
.tile:hover .tileImg,
.tile:focus-within .tileImg,
.tile:hover .tileFallback,
.tile:focus-within .tileFallback {
  transform: translate(-50%, -50%) scale(1.1) translateZ(0);
}

.previewStage {
  position: relative;
  width: 100%;
  padding: 28px 20px;
  border-radius: 10px;
  background: linear-gradient(
    180deg,
