    var(--rk-fg) 100%
  );
  color: var(--rk-bg);
}
.previewList {
  display: grid;
  grid-template-columns: 1fr;
  row-gap: 12px;
  width: 100%;
  margin: 0;
  padding: 0;
  list-style: none;
}

@media only screen and (min-width: 1024px) {
