    margin-left: 1.5px;
  }
  .title,
  .tileTitle {
    font-size: min(1.80556vw, 3.20988vh);
  }
  .price,
  .specTable {
    font-size: min(18px, min(1.25vw, 2.22222vh));
  }
  .previewStage {
    left: 50%;
    width: fit-content;
    max-width: calc(100vw - 40px);
    padding: 48px 44px;
    transform: translateX(-50%);
  }
  .previewList {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 0;
    width: calc(65.03vw - 25px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cardLink,
  .tileImg,
  .tileFallback,
  .tileHover {
    transition: none;
