section/collection-split-showcase.code:
"use client";

import { useEffect, useRef, useState, type MouseEvent } from "react";
import gsap from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import Swiper from "swiper";
import { Controller, EffectFade, Navigation } from "swiper/modules";
import "swiper/css";
import "swiper/css/effect-fade";
import styles from "./styles.module.css";

export interface CollectionProductItem { id: string; name: string; price?: number; imageSrc: string; }
export interface CollectionSlideData {
  id: string; title: string; description: string; brandLogoSrc?: string;
  visualImageSrc: string; visualAlt: string; shopLabel?: string;
  learnMoreLabel?: string; learnMoreHref?: string; bags: CollectionProductItem[];
}
export interface CollectionSplitShowcaseProps {
  id?: string; heading?: string; viewAllLabel?: string; viewAllHref?: string;
  selectedIndex?: number; collections?: CollectionSlideData[];
  onViewAllClick?: (event: MouseEvent<HTMLAnchorElement>) => void;
  onSelectProduct?: (product: CollectionProductItem, series: CollectionSlideData) => void;
  onLearnMoreClick?: (series: CollectionSlideData, event: MouseEvent<HTMLAnchorElement>) => void;
  /** Formats a product price for its title tooltip. Default: `$${value}`. Products without a price show only their name. */
  formatPrice?: (value: number) => string; selectProductLabel?: (name: string, priceLabel: string) => string;
  prevLabel?: string; nextLabel?: string; prevMobileLabel?: string; nextMobileLabel?: string;
}

const ARROW_PATHS = {
  left: "M5.321 11.833c.941.947 2.776 2.652 4.115 3.897.53.493.972.905 1.23 1.147l-2.179 2.064c-1.39-1.918-5.56-6.024-7.97-7.842V8.133C2.928 6.313 7.096 2.207 8.49.29l2.178 2.064c-.5.476-1.205 1.134-1.951 1.827C7.45 5.36 6.019 6.696 5.32 7.397l-.635.639h16.638c.616 0 1.231-.077 1.825-.15.285-.036.574-.071.859-.098v3.653a24.275 24.275 0 0 1-.851-.097c-.602-.075-1.217-.152-1.833-.152H4.686l.635.64v.001Z",
  right: "M19.678 11.833c-.94.947-2.775 2.652-4.114 3.897-.53.493-.972.905-1.23 1.147l2.179 2.064c1.39-1.918 5.56-6.024 7.97-7.842V8.133c-2.41-1.82-6.578-5.926-7.972-7.844l-2.178 2.064c.5.476 1.205 1.134 1.951 1.827 1.265 1.18 2.697 2.516 3.395 3.217l.635.639H3.676c-.616 0-1.231-.077-1.825-.15a26.726 26.726 0 0 0-.859-.098v3.653c.285-.026.572-.061.851-.097.602-.075 1.217-.152 1.833-.152h16.638l-.636.64v.001Z",
};

function ArrowIcon({ dir }: { dir: "left" | "right" }) {
  return (
    <svg viewBox="0 0 25 19" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <path d={ARROW_PATHS[dir]} fill="currentColor" />
    </svg>
  );
}

const DEFAULT_BAG_SVG =
  "data:image/svg+xml;utf8," +
  encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 530"><rect x="76" y="74" width="268" height="370" rx="18" fill="whitesmoke" stroke="lightgray" stroke-width="4"/><rect x="76" y="255" width="268" height="92" fill="firebrick"/><text x="210" y="220" text-anchor="middle" font-family="Arial,sans-serif" font-size="38" font-weight="700" fill="black">RESERVE</text></svg>',
  );

const DEFAULT_COLLECTIONS: CollectionSlideData[] = [
  {
    id: "limited-series",
    title: "Limited Series",
    description:
      "These represent the highest echelon of quality we source with partner farms every harvest. Each lot is grown in tiny quantities, making every release truly rare. Expect uncommon varieties, careful drying, and a vibrant cup. You owe it to yourself to brew one of these; it may shift how you taste coffee. Too bold? Not at all.",
    visualImageSrc: "https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=1200&q=80&auto=format&fit=crop",
    visualAlt: "Misty mountain ridge above evergreens at dawn",
    bags: [
      { id: "lot-01", name: "Pacamara Reserve", price: 36, imageSrc: DEFAULT_BAG_SVG },
      { id: "lot-02", name: "Pink Bourbon", price: 34, imageSrc: DEFAULT_BAG_SVG },
      { id: "lot-03", name: "Limited Decaf", price: 32, imageSrc: DEFAULT_BAG_SVG },
      { id: "lot-04", name: "Gold Selection", price: 40, imageSrc: DEFAULT_BAG_SVG },
    ],
  },
  {
    id: "bright-series",
    title: "Bright Series",
    description:
      "Developed with bright aromatic flavors and crisp orchard fruit clarity in mind. Each light roast performs cleanly as filter or modern espresso, rewarding careful extraction with floral aromatics and a lively finish.",
    visualImageSrc: "https://images.unsplash.com/photo-1441974231531-c6227db76b6e?w=1200&q=80&auto=format&fit=crop",
    visualAlt: "Sunlit forest path filtering golden light through tall trees",
    bags: [
      { id: "lot-05", name: "Solstice Washed", price: 27, imageSrc: DEFAULT_BAG_SVG },
      { id: "lot-06", name: "Kirinyaga AA", price: 28, imageSrc: DEFAULT_BAG_SVG },
      { id: "lot-07", name: "Tarrazu Honey", price: 26, imageSrc: DEFAULT_BAG_SVG },
      { id: "lot-08", name: "Cantaloupe Lot", price: 28, imageSrc: DEFAULT_BAG_SVG },
    ],
  },
];

export function CollectionSplitShowcase({
  id = "collections",
  heading = "Collections",
  viewAllLabel = "View all",
  viewAllHref = "#collections",
  selectedIndex,
  collections = DEFAULT_COLLECTIONS,
  onViewAllClick,
  onSelectProduct,
  onLearnMoreClick,
  formatPrice = (value) => `$${value}`, selectProductLabel = (name, priceLabel) => `Select ${name} (${priceLabel})`,
  prevLabel = "Slide left", nextLabel = "Slide right", prevMobileLabel = "Previous slide", nextMobileLabel = "Next slide",
}: CollectionSplitShowcaseProps) {
  const sectionRef = useRef<HTMLElement | null>(null);
  const visualSwiperElRef = useRef<HTMLDivElement | null>(null);
  const detailsSwiperElRef = useRef<HTMLDivElement | null>(null);
  const mobileSwiperElRef = useRef<HTMLDivElement | null>(null);
  const productsWrapperRef = useRef<HTMLDivElement | null>(null);
  const prevBtnRef = useRef<HTMLButtonElement | null>(null);
  const nextBtnRef = useRef<HTMLButtonElement | null>(null);
  const prevMobileBtnRef = useRef<HTMLButtonElement | null>(null);
  const nextMobileBtnRef = useRef<HTMLButtonElement | null>(null);
  const visualSwiperRef = useRef<Swiper | null>(null);
  const mobileSwiperRef = useRef<Swiper | null>(null);
  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    if (selectedIndex !== undefined && selectedIndex >= 0 && selectedIndex < collections.length) {
      visualSwiperRef.current?.slideTo(selectedIndex);
      mobileSwiperRef.current?.slideTo(selectedIndex);
      setActiveIndex(selectedIndex);
    }
  }, [selectedIndex, collections.length]);

  useEffect(() => {
    gsap.registerPlugin(ScrollTrigger);
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const ctx = gsap.context(() => {
      const mm = gsap.matchMedia();
      mm.add("(min-width: 1024px)", () => {
        if (!visualSwiperElRef.current || !detailsSwiperElRef.current || !productsWrapperRef.current) return;
        const detailsSwiper = new Swiper(detailsSwiperElRef.current, {
          modules: [EffectFade, Controller],
          speed: reducedMotion ? 0 : 600,
          effect: "fade",
          fadeEffect: { crossFade: true },
          allowTouchMove: false,
        });
        const visualSwiper = new Swiper(visualSwiperElRef.current, {
          modules: [Navigation, Controller],
          navigation: { nextEl: nextBtnRef.current, prevEl: prevBtnRef.current },
          speed: reducedMotion ? 0 : 600,
          grabCursor: true,
          controller: { control: detailsSwiper },
        });
        visualSwiperRef.current = visualSwiper;
        visualSwiper.on("slideChange", () => setActiveIndex(visualSwiper.activeIndex));
        const stDesktop = reducedMotion
          ? null
          : gsap.to(productsWrapperRef.current, {
              xPercent: -300 / 4,
              scrollTrigger: { trigger: productsWrapperRef.current, scrub: 2, start: "top 70%", end: "bottom 30%" },
            });
        return () => {
          detailsSwiper.destroy(true, false);
          visualSwiper.destroy(true, false);
          visualSwiperRef.current = null;
          stDesktop?.scrollTrigger?.kill();
          stDesktop?.kill();
        };
      });
      mm.add("(max-width: 1023px)", () => {
        if (!mobileSwiperElRef.current) return;
        const mobileSwiper = new Swiper(mobileSwiperElRef.current, {
          modules: [Navigation],
          navigation: { nextEl: nextMobileBtnRef.current, prevEl: prevMobileBtnRef.current },
          speed: reducedMotion ? 0 : 600,
          autoHeight: true,
        });
        mobileSwiperRef.current = mobileSwiper;
        mobileSwiper.on("slideChange", () => setActiveIndex(mobileSwiper.activeIndex));
        return () => {
          mobileSwiper.destroy(true, false);
          mobileSwiperRef.current = null;
        };
      });
    }, sectionRef);
    return () => ctx.revert();
  }, [collections.length]);

  return (
    <section ref={sectionRef} id={id} className={styles.section} aria-label={heading}>
      <div className={styles.homeCollections}>
        <div className={`${styles.sliderHeader} ${styles.grid} ${styles.padX}`}>
          <h2 className={styles.headerTitle}>{heading}</h2>
          <a href={viewAllHref} className={styles.viewAll} onClick={onViewAllClick}>{viewAllLabel}</a>
          <div className={styles.sliderHeaderButtons}>
            <button ref={prevBtnRef} type="button" className={`${styles.swiperBtn} ${styles.prevBtn} ${activeIndex === 0 ? styles.swiperBtnDisabled : ""}`} aria-label={prevLabel}><ArrowIcon dir="left" /></button>
            <button ref={nextBtnRef} type="button" className={`${styles.swiperBtn} ${styles.nextBtn} ${activeIndex >= collections.length - 1 ? styles.swiperBtnDisabled : ""}`} aria-label={nextLabel}><ArrowIcon dir="right" /></button>
          </div>
        </div>

        <div className={`${styles.innerDesktop} ${styles.grid} ${styles.padX}`}>
          <div ref={visualSwiperElRef} className={`${styles.visuals} swiper`} aria-hidden="true">
            <div className="swiper-wrapper">
              {collections.map((series, idx) => (
                <div key={series.id} className={`swiper-slide ${styles.visualSlide} ${activeIndex === idx ? styles.slideActive : ""}`}>
                  {series.brandLogoSrc ? (
                    <img src={series.brandLogoSrc} className={styles.brandLogo} alt={series.title} />
                  ) : (
                    <div className={`${styles.brandLogo} ${styles.brandBadge}`}>{series.title}</div>
                  )}
                  <div className={styles.visualWrapper}>
                    <div className={styles.mediaInner}><img src={series.visualImageSrc} className={styles.visualImg} alt={series.visualAlt} /></div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          <div className={styles.infos}>
            <div className={styles.products}>
              <div ref={productsWrapperRef} className={styles.productsWrapper}>
                {collections.map((series, idx) => (
                  <div key={series.id} className={`${styles.productsLine} ${activeIndex === idx ? styles.productsLineActive : ""}`}>
                    {series.bags.map((bag) => (
                      <button key={bag.id} type="button" className={styles.productMedia} tabIndex={activeIndex === idx ? 0 : -1} onClick={() => onSelectProduct?.(bag, series)} title={bag.price ? selectProductLabel(bag.name, formatPrice(bag.price)) : bag.name}>
                        <img src={bag.imageSrc} alt={bag.name} />
                      </button>
                    ))}
                  </div>
                ))}
              </div>
            </div>

            <div ref={detailsSwiperElRef} className={`${styles.details} swiper`}>
              <div className="swiper-wrapper">
                {collections.map((series, idx) => (
                  <div key={series.id} className={`swiper-slide ${styles.detailSlide} ${activeIndex === idx ? styles.slideActive : ""}`}>
                    <div className={styles.detailInner}>
                      <h3 className={styles.detailTitle}>{series.title}</h3>
                      <div className={styles.detailBody}><p>{series.description}</p></div>
                      <button type="button" className={`${styles.btn} ${styles.btnSolid}`} tabIndex={activeIndex === idx ? 0 : -1} onClick={() => series.bags[0] && onSelectProduct?.(series.bags[0], series)}>{series.shopLabel ?? "Shop"}</button>
                      <a href={series.learnMoreHref ?? "#mission"} className={`${styles.btn} ${styles.btnGhost}`} tabIndex={activeIndex === idx ? 0 : -1} onClick={(e) => onLearnMoreClick?.(series, e)}>{series.learnMoreLabel ?? "Learn More"}</a>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className={styles.innerMobile}>
          <div className={styles.infos}>
            <div className={`${styles.mobileButtons} ${styles.padX}`}>
              <button ref={prevMobileBtnRef} type="button" className={`${styles.swiperBtn} ${activeIndex === 0 ? styles.swiperBtnDisabled : ""}`} aria-label={prevMobileLabel}><ArrowIcon dir="left" /></button>
              <button ref={nextMobileBtnRef} type="button" className={`${styles.swiperBtn} ${activeIndex >= collections.length - 1 ? styles.swiperBtnDisabled : ""}`} aria-label={nextMobileLabel}><ArrowIcon dir="right" /></button>
            </div>
            <div ref={mobileSwiperElRef} className={`${styles.details} swiper`}>
              <div className="swiper-wrapper">
                {collections.map((series, idx) => (
                  <div key={series.id} className={`swiper-slide ${styles.padX} ${styles.detailSlide} ${activeIndex === idx ? styles.slideActive : ""}`}>
                    <div className={styles.mobileVisualWrapper}>
                      <div className={styles.mediaInner}><img src={series.visualImageSrc} className={styles.visualImg} alt={series.visualAlt} /></div>
                    </div>
                    <div className={styles.detailInner}>
                      <h3 className={styles.detailTitle}>{series.title}</h3>
                      <div className={styles.detailBody}><p>{series.description}</p></div>
                      <button type="button" className={`${styles.btn} ${styles.btnSolid}`} onClick={() => series.bags[0] && onSelectProduct?.(series.bags[0], series)}>{series.shopLabel ?? "Shop"}</button>
                      <a href={series.learnMoreHref ?? "#mission"} className={`${styles.btn} ${styles.btnGhost}`} onClick={(e) => onLearnMoreClick?.(series, e)}>{series.learnMoreLabel ?? "Learn More"}</a>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

section/collection-split-showcase.stylesCss:
.section {
  --columns: 6;
  --gutters: 15px;
  --outsideGutters: 20px;
  --col: calc((100vw - (var(--outsideGutters) * 2) - (var(--gutters) * (var(--columns) - 1))));
  display: block;
  width: 100%;
  padding: 0;
  background-color: var(--rk-bg);
  color: var(--rk-fg);
  font-family: var(--rk-font-body);
  font-size: 16px;
  font-weight: 300;
  line-height: 1;
}
.homeCollections { display: block; }
.grid { position: relative; display: grid; grid-template-columns: repeat(var(--columns), 1fr); column-gap: var(--gutters); }
.padX { padding-left: var(--outsideGutters); padding-right: var(--outsideGutters); }

.sliderHeader { align-items: center; margin-bottom: 25px; padding-top: 30px; }
.headerTitle { margin: 0; padding: 0; grid-column: span 3; font-family: var(--rk-font-body); font-size: 22px; font-weight: 300; line-height: 1.05; color: var(--rk-fg); }
.viewAll {
  display: inline-block;
  grid-column: span 3;
  width: fit-content;
  margin-left: auto;
  text-align: right;
  font-family: var(--rk-font-body);
  font-size: 14px;
  font-weight: 300;
  line-height: 1.35;
  color: var(--rk-fg);
  text-decoration: underline;
  text-underline-offset: 0.3rem;
  cursor: pointer;
}
.sliderHeaderButtons { text-align: right; grid-column: span 2; }
.mobileButtons { display: flex; justify-content: flex-start; margin-bottom: 20px; }

.swiperBtn {
  position: relative;
  display: inline-block;
  width: 56px;
  height: 56px;
  padding: 0;
  border: 2px solid currentColor;
  border-radius: 50%;
  background: transparent;
  color: var(--rk-fg);
  font-family: var(--rk-font-body);
  font-size: 13.3333px;
  font-weight: 400;
  line-height: normal;
  text-align: center;
  cursor: pointer;
  transition: color 0.6s cubic-bezier(0.215, 0.61, 0.355, 1);
}
.swiperBtn + .swiperBtn { margin-left: 20px; }
.prevBtn, .nextBtn { vertical-align: baseline; }
.swiperBtn:global(.swiper-button-disabled), .swiperBtnDisabled { color: var(--rk-surface); }
.swiperBtn svg {
  display: block;
  width: 24px;
  height: 18px;
  margin: 0 auto;
  transform: scale(1) translateZ(0);
  transition: transform 0.6s cubic-bezier(0.215, 0.61, 0.355, 1);
}
.swiperBtn:not(:disabled):not(:global(.swiper-button-disabled)):hover svg,
.swiperBtn:not(:disabled):not(:global(.swiper-button-disabled)):active svg { transform: scale(1.1) translateZ(0); }

.innerDesktop { display: none; }
.innerMobile { display: block; }

.visuals { width: 100%; aspect-ratio: 871 / 1096; grid-column: span 8; border-radius: 4px; }
.visualSlide { display: flex; flex-direction: column; justify-content: center; align-items: center; transition-timing-function: cubic-bezier(0.215, 0.61, 0.355, 1); }
.brandLogo {
  display: block;
  width: 32%;
  z-index: 1;
  opacity: 0;
  transform: translateY(40px) translateZ(0);
  transition: opacity 0.6s cubic-bezier(0.55, 0.055, 0.675, 0.19), transform 0.6s cubic-bezier(0.55, 0.055, 0.675, 0.19);
}
.brandBadge {
  position: relative;
  z-index: 1;
  width: 32%;
  padding: 16px 20px;
  border-radius: 6px;
  background-color: var(--rk-surface-elevated);
  color: var(--rk-fg);
  font-family: var(--rk-font-display);
  font-size: min(3.125vw, 5.5555555556vh);
  font-weight: 700;
  line-height: 0.9;
  text-transform: uppercase;
  text-align: center;
}
.visualSlide:global(.swiper-slide-active) .brandLogo, .slideActive .brandLogo {
  opacity: 1;
  transform: translateY(0) translateZ(0);
  transition: opacity 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) 0.6s, transform 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) 0.6s;
}
.visualWrapper { position: absolute; top: 0; left: 0; width: 100%; height: 100%; }
.mobileVisualWrapper { position: relative; aspect-ratio: 871 / 1096; width: 100%; border-radius: 4px; overflow: hidden; margin-bottom: 20px; }
.mediaInner { position: absolute; top: 0; left: 0; width: 100%; height: 100%; }
.mediaInner::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  background: color-mix(in srgb, var(--rk-fg) 48%, var(--rk-bg));
  mix-blend-mode: overlay;
  opacity: 0.25;
  pointer-events: none;
}
.visualImg { position: absolute; top: 0; left: 0; width: 100%; height: 100%; display: block; object-fit: cover; }

.infos { width: 100%; grid-column: span 6; display: block; }
.products { position: relative; aspect-ratio: 423 / 537; background-color: var(--rk-surface); margin-bottom: 25px; border-radius: 4px; overflow: hidden; }
.productsWrapper { position: absolute; top: 0; left: 0; width: 400%; height: 100%; }
.productsLine { display: flex; flex-wrap: nowrap; pointer-events: none; }
.productsLineActive { opacity: 1; pointer-events: auto; }
.productMedia { width: 25%; height: 100%; border: 0; padding: 0; background: transparent; cursor: pointer; transition: transform 0.3s ease; }
.productMedia:hover { transform: translateY(-6px); }
.productMedia img { width: 100%; height: 100%; object-fit: contain; display: block; }

.details { width: 100%; }
.detailSlide { padding-bottom: 10px; }
.detailInner {
  padding-bottom: 40px;
  opacity: 0;
  transform: translateY(40px) translateZ(0);
  transition: opacity 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) 0.3s, transform 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) 0.3s;
}
.detailSlide:global(.swiper-slide-active) .detailInner, .slideActive .detailInner {
  opacity: 1;
  transform: translateY(0) translateZ(0);
  transition: opacity 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) 0.6s, transform 0.6s cubic-bezier(0.215, 0.61, 0.355, 1) 0.6s;
}
.detailTitle { margin: 0; padding: 0; font-family: var(--rk-font-display); font-size: 36px; font-weight: 300; line-height: 0.85; text-transform: uppercase; color: var(--rk-fg); }
.detailBody { margin-top: 20px; margin-bottom: 20px; font-family: var(--rk-font-body); font-size: 16px; font-weight: 300; line-height: 1.35; color: var(--rk-fg); }
.detailBody p { margin: 0; }

.btn {
  position: relative;
  display: inline-block;
  padding: 5px;
  border-radius: 3px;
  font-family: var(--rk-font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.6s cubic-bezier(0.215, 0.61, 0.355, 1), color 0.6s cubic-bezier(0.215, 0.61, 0.355, 1), border-color 0.6s cubic-bezier(0.215, 0.61, 0.355, 1);
}
.btn + .btn { margin-left: 10px; }
.btnSolid { border: 0; background-color: var(--rk-fg); color: var(--rk-bg); }
.btnGhost { border: 1.25px solid var(--rk-fg); background-color: transparent; color: var(--rk-fg); }
.btn:hover, .btn:active { background-color: var(--rk-surface-elevated); color: var(--rk-fg); border-color: transparent; }

.btn:focus-visible, .swiperBtn:focus-visible, .viewAll:focus-visible, .productMedia:focus-visible { outline: 2px solid var(--rk-accent); outline-offset: 2px; }

@media only screen and (max-width: 1023px) {
  .sliderHeaderButtons { display: none; }
}

@media only screen and (min-width: 1024px) {
  .section { --columns: 12; --gutters: 20px; --outsideGutters: 52px; }
  .homeCollections { padding: 100px 0; }
  .sliderHeader { padding-top: 0; margin-bottom: 60px; }
  .headerTitle { grid-column-start: 1; grid-column-end: 9; font-size: min(1.9444444444vw, 3.4567901235vh); }
  .viewAll { grid-column: span 2; font-size: min(16px, min(1.1111111111vw, 1.975308642vh)); }
  .swiperBtn { width: min(3.8888888889vw, 6.9135802469vh); height: min(3.8888888889vw, 6.9135802469vh); }
  .swiperBtn svg { width: min(1.6666666667vw, 2.962962963vh); height: min(1.25vw, 2.2222222222vh); }
  .innerDesktop { display: grid; }
  .innerMobile { display: none; }
  .infos { grid-column: span 4; }
  .productsLine { position: absolute; top: 0; left: 0; width: 100%; height: 100%; opacity: 0; transition: opacity 0.6s cubic-bezier(0.55, 0.055, 0.675, 0.19); }
  .productsLineActive { opacity: 1; }
  .detailTitle { font-size: min(3.125vw, 5.5555555556vh); }
  .detailBody { font-size: min(18px, min(1.25vw, 2.2222222222vh)); }
  .btn { padding: min(0.3472222222vw, 0.6172839506vh); font-size: min(1.8055555556vw, 3.2098765432vh); }
}

@media (prefers-reduced-motion: reduce) {
  .swiperBtn, .swiperBtn svg, .brandLogo, .productsLine, .productMedia, .detailInner, .btn { transition: none; }
  .brandLogo, .detailInner { opacity: 1; transform: none; }
}

