export function EditorialStorefrontHero({
  taglineWords = ["Go", "Against", "the", "Grain"],
  description = "Small-batch specialty coffee roasted for clarity, sweetness, and daily ritual.",
  ctaLabel = "Shop Now",
  ctaHref = "#collections",
  moodHeading = "A small-batch specialty coffee company",
  moodIcon,
  marqueeText = "new * Fresh off the tree * New",
  backgroundImage,
  backgroundAlt = "",
  products = DEFAULT_PRODUCTS,
  specLabels = { type: "Type:", origin: "Origin:", process: "Process:" },
  onProductClick,
}: EditorialStorefrontHeroProps) {
  const rootRef = useRef<HTMLElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const imgInnerRef = useRef<HTMLDivElement>(null);
  const btnWrapperRef = useRef<HTMLDivElement>(null);
  const btnRef = useRef<HTMLAnchorElement>(null);
  const descRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const lines = Array.from(root.querySelectorAll<HTMLElement>("[data-anim-lines]"));
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      lines.forEach((el) => el.classList.add(styles.linesActive));
      return;
    }
    gsap.registerPlugin(ScrollTrigger);
    const ctx = gsap.context(() => {
      const chars = Array.from(root.querySelectorAll<HTMLElement>("[data-char]"));
      let xIndex = 0;
      let yIndex = 0;
      root.querySelectorAll<HTMLElement>("[data-word]").forEach((word, wIdx) => {
        let animI = wIdx % 2 ? 1 : 0;
        Array.from(word.children).forEach((node, subIdx) => {
          const opts: gsap.TweenVars = { opacity: 0 };
          if ((subIdx + animI) % 3 === 0) opts.xPercent = xIndex++ % 2 ? 50 : -50;
          else if (animI % 2 === 0) opts.yPercent = yIndex++ % 2 ? -70 : 70;
          (node as HTMLElement).dataset.stagger = String(gsap.utils.random(0.1, 0.6));
          gsap.set(node, opts);
          animI++;
        });
      });
      const stagger = (_i: number, el: Element) => parseFloat((el as HTMLElement).dataset.stagger ?? "0.2");
      const tl = gsap.timeline({ delay: 0.2, scrollTrigger: { trigger: root, once: true } });
      tl.to(chars, { xPercent: 0, yPercent: 0, ease: "expo.out", duration: 1.4, stagger }, 0);
      tl.to(chars, { opacity: 1, ease: "expo.out", duration: 0.8, stagger }, 0);
      lines.forEach((el) =>
        ScrollTrigger.create({ trigger: el, start: "top 85%", once: true, onEnter: () => el.classList.add(styles.linesActive) }),
      );

      const img = imgInnerRef.current;
      const wrapper = wrapperRef.current;
      const btn = btnRef.current;
      const btnWrapper = btnWrapperRef.current;
      const desc = descRef.current;
      if (!img || !wrapper || !btn || !btnWrapper || !desc) return;
      const mm = gsap.matchMedia();
      mm.add("(min-width: 1024px) and (orientation: landscape)", () => {
        gsap.set([btn, desc], { y: 40, opacity: 0 });
        gsap.to(img, { scale: 1, ease: "power2.inOut", duration: 1.4, scrollTrigger: { trigger: img } });
        gsap.to(btn, { y: 0, opacity: 1, ease: "power2.out", duration: 0.6, delay: 0.8, scrollTrigger: { trigger: btn } });
        gsap.to(img, { yPercent: 25, scrollTrigger: { trigger: wrapper, scrub: true, start: "top top", end: "bottom top" } });
        gsap.to(btnWrapper, {
          scale: 1,
          scrollTrigger: {
            trigger: wrapper,
            pin: btnWrapper,
            scrub: 1,
            start: "top top",
            end: () => {
              const dist =
                desc.getBoundingClientRect().bottom - btn.getBoundingClientRect().bottom + desc.offsetHeight - 20;
              return `+=${Math.max(120, dist)}`;
            },
            invalidateOnRefresh: true,
          },
        });
        gsap.to(desc, { y: 0, opacity: 1, ease: "power2.out", duration: 0.6, scrollTrigger: { trigger: desc, start: "top 80%" } });
      });
      mm.add("(max-width: 1023px)", () => {
        gsap.to(img, { scale: 1, ease: "power2.inOut", duration: 1.4, scrollTrigger: { trigger: img } });
        gsap.to(img, { yPercent: 18, scrollTrigger: { trigger: wrapper, scrub: true, start: "top top", end: "bottom top" } });
      });
    }, root);
    return () => ctx.revert();
  }, [taglineWords]);

  return (
    <section ref={rootRef} className={styles.hero}>
      <div ref={wrapperRef} className={styles.wrapper}>
        <div className={styles.media}>
          <div ref={imgInnerRef} className={styles.mediaInner}>
            {backgroundImage ? <img src={backgroundImage} alt={backgroundAlt} className={styles.mediaImg} /> : null}
          </div>
        </div>

        <h1 className={styles.srOnly}>{taglineWords.join(" ")}</h1>
        <div className={styles.grid}>
          <div className={styles.tagline} aria-hidden="true">
            {taglineWords.map((word, wIdx) => (
              <div key={`${word}-${wIdx}`} className={styles.taglineLine}>
                <span data-word="" className={styles.word}>
                  {Array.from(word).map((ch, cIdx) => (
                    <span key={cIdx} data-char="" className={styles.char}>
                      {ch}
                    </span>
                  ))}
                </span>
              </div>
            ))}
          </div>
        </div>

        <div className={styles.grid}>
          <p className={styles.srOnly}>{description}</p>
          <div ref={descRef} data-anim-lines="" className={`${styles.desc} ${styles.lines}`} aria-hidden="true">
            <div>{description}</div>
          </div>
        </div>

        <div ref={btnWrapperRef} className={styles.btnWrapper}>
          <a ref={btnRef} href={ctaHref} className={styles.btn}>
            {ctaLabel}
          </a>
        </div>

        <div className={styles.push}>
          <div className={`${styles.mood} ${styles.block}`}>
            <h2 className={styles.srOnly}>{moodHeading}</h2>
            <div data-anim-lines="" className={`${styles.moodHeading} ${styles.lines}`} aria-hidden="true">
              {moodHeading}
            </div>
            {moodIcon ?? <MugIcon />}
          </div>

          <div className={styles.products}>
            <ul className={styles.list}>
              {products.slice(0, 3).map((product) => (
                <li key={product.id} className={`${styles.product} ${styles.block}`}>
                  <a
                    href={product.href ?? "#"}
                    className={styles.productLink}
                    onClick={onProductClick ? (e) => onProductClick(product, e) : undefined}
                  >
                    <div className={styles.infos}>
                      <h3 className={styles.productTitle}>{product.title}</h3>
                      <p className={styles.productPrice}>{product.price}</p>
                    </div>
                    <table className={styles.spec}>
                      <tbody>
                        <tr><td>{specLabels.type}</td><td className={styles.bold}>{product.type}</td></tr>
                        <tr><td>{specLabels.origin}</td><td className={styles.bold}>{product.origin}</td></tr>
                        <tr><td>{specLabels.process}</td><td className={styles.bold}>{product.process}</td></tr>
                      </tbody>
                    </table>
                  </a>
                </li>
              ))}
            </ul>

            <div className={`${styles.ticker} ${styles.block}`} aria-hidden="true">
              <div>
                {Array.from({ length: 5 }).map((_, i) => <ArrowUpIcon key={`a-${i}`} />)}
                <p className={styles.tickerText}>{marqueeText}</p>
                {Array.from({ length: 5 }).map((_, i) => <ArrowUpIcon key={`b-${i}`} />)}
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

section/editorial-storefront-hero.stylesCss:
.hero {
  --columns: 6;
  --gutters: 15px;
  --outsideGutters: 20px;
  position: relative;
  width: 100%;
  background: var(--rk-fg);
  color: var(--rk-bg);
  font-family: var(--rk-font-body);
  font-weight: 300;
  line-height: 1;
}
.wrapper { position: relative; }

.media {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
}
.media::after {
  content: "";
  position: absolute;
  inset: 0;
  background-color: color-mix(in srgb, var(--rk-fg) 15%, transparent);
}
.mediaInner {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  transform: scale(1.2);
  transform-origin: 50% 0%;
}
.mediaInner::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  background: color-mix(in srgb, var(--rk-fg) 48%, var(--rk-bg));
  mix-blend-mode: overlay;
  opacity: 0.25;
  pointer-events: none;
}
.mediaImg {
  position: absolute;
  top: 0;
  left: 0;
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 0%;
}

.grid {
  position: relative;
  display: grid;
  grid-template-columns: repeat(var(--columns), 1fr);
  column-gap: var(--gutters);
  padding-left: var(--outsideGutters);
  padding-right: var(--outsideGutters);
}

.tagline {
  grid-column: span 6;
  padding-top: 130px;
  padding-bottom: 70px;
  font-family: var(--rk-font-display);
  font-size: min(24vw, 13.4933vh);
  font-weight: 700;
  line-height: 0.85;
  letter-spacing: -0.02em;
  text-transform: uppercase;
}
.taglineLine { white-space: nowrap; }
.word,
.char { display: inline-block; }
.char { position: relative; will-change: transform, opacity; }

.desc,
.btn,
.productTitle,
.tickerText {
  font-family: var(--rk-font-display);
  font-size: 22px;
  font-weight: 700;
  line-height: 1;
  text-transform: uppercase;
}
/* Substitute-font compensation (Molitor -> Oswald): -0.01em keeps the original line
   breaks: 4 lines in the 293px column at 1024, 3 lines at 1920 and in the 562px column
   of the calc(100vw - 90px) template. */
.desc { display: block; grid-column: span 6; letter-spacing: -0.01em; }

.lines {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.8s cubic-bezier(0.215, 0.61, 0.355, 1), transform 0.8s cubic-bezier(0.215, 0.61, 0.355, 1);
}
.linesActive { opacity: 1; transform: translateY(0); }

.btnWrapper { margin-top: 20px; padding: 0 var(--outsideGutters) 80px; }
.wrapper :global(.pin-spacer) { mix-blend-mode: lighten; }
.btn {
  display: inline-block;
  padding: 5px;
  border-radius: 3px;
  white-space: nowrap;
  background-color: var(--rk-bg);
  color: var(--rk-fg);
  text-decoration: none;
  mix-blend-mode: lighten;
}
.btn:hover { background-color: var(--rk-fg); color: var(--rk-surface-elevated); }

.push { display: none; }
.block { border-radius: 10px; box-shadow: 0 0 0 1.5px currentColor; }
.mood {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 30vw;
  padding: 15px 25px;
  text-align: center;
  text-transform: uppercase;
}
.moodHeading {
  font-family: var(--rk-font-display);
  font-size: 36px;
  line-height: 0.85;
  text-transform: uppercase;
  /* Substitute-font compensation (Molitor -> Oswald): the heading sets 830px vs 878px
     over 34 glyphs at 54.4px (1920), i.e. ~0.026em narrower per glyph. */
  letter-spacing: 0.026em;
}
.mood svg { display: block; width: 60px; margin-top: 15px; }

.products { display: flex; flex-direction: column; flex-grow: 1; }
.list {
  display: grid;
  flex-grow: 1;
  margin: 0;
  padding: 0;
  list-style: none;
}
.product { display: block; height: 100%; overflow: hidden; }
.product + .product { margin-left: 1.5px; }
.productLink {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  height: 100%;
  padding: 15px 20px;
  background-color: transparent;
  color: inherit;
  text-decoration: none;
  transition: background-color 0.6s cubic-bezier(0.37, 0.31, 0, 1), color 0.6s cubic-bezier(0.37, 0.31, 0, 1);
}
.productLink:hover { background-color: var(--rk-bg); color: var(--rk-fg); }
.productTitle { margin: 0 0 40px; }
.infos { display: flex; column-gap: 20px; }
.productPrice { margin: 0 0 0 auto; font-size: 16px; line-height: 1.35; }
.spec {
  margin-top: auto;
  font-family: var(--rk-font-narrow, var(--rk-font-display));
  font-size: 15px;
  line-height: 1;
  text-transform: uppercase;
  /* Substitute-font compensation (Garaje -> Barlow Condensed): the spec copy sets
     917px vs 813px over 171 glyphs at 12.8px, i.e. ~0.048em wider per glyph. */
  letter-spacing: -0.048em;
}
.spec tr { display: grid; grid-template-columns: 70px auto; column-gap: 20px; }
.spec tr + tr { margin-top: 5px; }
.bold { font-weight: 700; }
.tickerText { margin: 0; }
.ticker svg { display: inline; vertical-align: baseline; }
.spec { border-collapse: collapse; }
.spec td { padding: 0; }

.btn:focus-visible,
.productLink:focus-visible { outline: 2px solid var(--rk-accent); outline-offset: 2px; }
.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media only screen and (min-width: 1024px) {
  .hero { --columns: 12; --gutters: 20px; --outsideGutters: 52px; }
  .tagline { grid-column: span 7; padding-top: 20vh; padding-bottom: 0; font-size: min(16.6667vw, 30.2469vh); }
  .desc, .btn, .productTitle, .tickerText { font-size: min(1.80556vw, 3.20988vh); }
  .btn { padding: min(0.347222vw, 0.617284vh); }
  .moodHeading { font-size: min(3.125vw, 5.55556vh); }
  .productPrice { font-size: min(18px, min(1.25vw, 2.22222vh)); }
  .spec { font-size: min(18px, min(1.25vw, 2.22222vh)); }
  .push { position: relative; display: flex; margin-top: 28vh; padding: 0 var(--outsideGutters) 50px; }
  .products { margin-left: 1.5px; }
  .list { grid-template-columns: 1fr 1fr 1fr; }
}
@media only screen and (min-width: 1280px) {
  .tagline { font-size: min(17.3611vw, 31.4815vh); }
}
@media only screen and (min-width: 1024px) and (orientation: portrait) {
  .tagline { padding-bottom: 70px; font-size: min(16.6667vw, 29.6296vh); }
}
@media only screen and (min-width: 1024px) and (orientation: landscape) {
  .desc { margin-top: 20vh; grid-column: 9 / 13; font-size: 1.80556vw; }
  .btnWrapper {
    position: absolute;
    top: 85vh;
    left: calc(var(--outsideGutters) + 8 * (100% - 2 * var(--outsideGutters) - 11 * var(--gutters)) / 12 + 8 * var(--gutters));
    z-index: 1;
    margin: 0;
    padding: 0;
    transform: scale(1.3) translateZ(0);
    transform-origin: 0% 100%;
  }
  .btn { mix-blend-mode: normal; }
}
@media (prefers-reduced-motion: reduce) {
  .lines, .productLink { transition: none; }
  .mediaInner { transform: none; }
}

