"use client";

import { useEffect, useRef, useState, type RefObject } from "react";
import * as THREE from "three";
import {
  MARK_ASPECT,
  MARK_TEX_H,
  MARK_TEX_PAD,
  MARK_TEX_W,
  RAYS_FRAGMENT_SHADER,
  RAYS_VERTEX_SHADER,
  createMarkTexture,
  readAccentTint,
} from "./rays-shaders";

const LIGHT_REST = { x: 0.454, y: 0.32 };
const POINTER_PULL = 0.28;
const LIGHT_RANGE = 0.46;
const SPRING_STIFFNESS = 70;
const SPRING_DAMPING = 8.5;

interface RaysTileProps {
  tileRef: RefObject<HTMLDivElement | null>;
  live: boolean;
  className?: string;
  fallbackClassName?: string;
}

export function RaysTile({ tileRef, live, className, fallbackClassName }: RaysTileProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const liveRef = useRef(live);
  liveRef.current = live;
  const [fallback, setFallback] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    const tile = tileRef.current;
    if (!canvas || !tile) return;

    const reducedMotion =
      typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
    const coarseMobile =
      typeof matchMedia === "function" &&
      matchMedia("(pointer: coarse)").matches &&
      Math.min(window.screen.width, window.screen.height) < 820;

    if (coarseMobile) {
      setFallback(true);
      return;
    }

    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({
        canvas,
        alpha: true,
        premultipliedAlpha: true,
        antialias: false,
        depth: false,
        stencil: false,
        powerPreference: "low-power",
      });
    } catch {
      setFallback(true);
      return;
    }

    renderer.setPixelRatio(1);
    renderer.setClearColor(0x000000, 0);

    const scene = new THREE.Scene();
    const camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    const markTexture = createMarkTexture();

    const uniforms = {
      uRes: { value: new THREE.Vector2(1, 1) },
      uLight: { value: new THREE.Vector2(0, 0) },
      uTileC: { value: new THREE.Vector2(0, 0) },
      uTileH: { value: new THREE.Vector2(1, 1) },
      uTileR: { value: 16 },
      uMarkH: { value: new THREE.Vector2(1, 1) },
      uMark: { value: markTexture },
      uSpread: { value: 180 },
      uIntensity: { value: 0.25 },
      uTint: { value: readAccentTint(tile) },
    };

    const geometry = new THREE.PlaneGeometry(2, 2);
    const material = new THREE.ShaderMaterial({
      vertexShader: RAYS_VERTEX_SHADER,
      fragmentShader: RAYS_FRAGMENT_SHADER,
      uniforms,
      depthTest: false,
      depthWrite: false,
    });
    scene.add(new THREE.Mesh(geometry, material));

    let renderScale = 1;
    let visible = true;
    let dirty = true;
    const pointer = { x: NaN, y: NaN };
    const light = { x: 0, y: 0, vx: 0, vy: 0, init: false };
    let lastTile = { cx: 0, cy: 0, w: 0 };

    const resize = () => {
      const dpr = Math.min(1, window.devicePixelRatio || 1);
      renderScale = Math.min(1, dpr * 0.6);
      const w = Math.max(1, Math.floor(canvas.clientWidth * renderScale));
      const h = Math.max(1, Math.floor(canvas.clientHeight * renderScale));
      renderer.setSize(w, h, false);
      uniforms.uRes.value.set(w, h);
      uniforms.uTint.value.copy(readAccentTint(tile));
      dirty = true;
    };
    resize();

    const ro = new ResizeObserver(resize);
    ro.observe(canvas);

    const io = new IntersectionObserver(
      ([entry]) => {
        visible = entry.isIntersecting;
        if (visible) dirty = true;
      },
      { threshold: 0 },
    );
    io.observe(canvas);

    const onPointerMove = (event: PointerEvent) => {
      pointer.x = event.clientX;
      pointer.y = event.clientY;
    };
    if (!reducedMotion) window.addEventListener("pointermove", onPointerMove, { passive: true });

    let raf = 0;
    let prevTime = performance.now();
    const frame = () => {
      raf = requestAnimationFrame(frame);
      const now = performance.now();
      const dt = Math.min(0.05, (now - prevTime) / 1000);
      prevTime = now;
      if (!visible || !liveRef.current) return;

      const canvasRect = canvas.getBoundingClientRect();
      const tileRect = tile.getBoundingClientRect();
      if (!tileRect.width) return;

      const cx = tileRect.left - canvasRect.left + tileRect.width / 2;
      const cy = tileRect.top - canvasRect.top + tileRect.height / 2;
      const halfW = tileRect.width / 2;
      const halfH = tileRect.height / 2;
      if (cx !== lastTile.cx || cy !== lastTile.cy || tileRect.width !== lastTile.w) {
        dirty = true;
        lastTile = { cx, cy, w: tileRect.width };
      }

      let targetX = cx + (LIGHT_REST.x - 0.5) * tileRect.width;
      let targetY = cy + (LIGHT_REST.y - 0.5) * tileRect.height;
      if (!reducedMotion && !Number.isNaN(pointer.x)) {
        targetX += (pointer.x - canvasRect.left - cx) * POINTER_PULL;
        targetY += (pointer.y - canvasRect.top - cy) * POINTER_PULL;
      }
      targetX = Math.max(cx - halfW * LIGHT_RANGE, Math.min(cx + halfW * LIGHT_RANGE, targetX));
      targetY = Math.max(cy - halfH * LIGHT_RANGE, Math.min(cy + halfH * LIGHT_RANGE, targetY));

      if (!light.init) {
        light.x = targetX;
        light.y = targetY;
        light.init = true;
        dirty = true;
      } else {
        light.vx += (targetX - light.x) * SPRING_STIFFNESS * dt;
        light.vy += (targetY - light.y) * SPRING_STIFFNESS * dt;
        const damping = Math.exp(-SPRING_DAMPING * dt);
        light.vx *= damping;
        light.vy *= damping;
        const nextX = light.x + light.vx * dt;
        const nextY = light.y + light.vy * dt;
        if (Math.abs(nextX - light.x) > 0.02 || Math.abs(nextY - light.y) > 0.02) dirty = true;
        light.x = nextX;
        light.y = nextY;
      }
      if (!dirty) return;
      dirty = false;

      tile.style.setProperty("--lx", `${(((light.x - (cx - halfW)) / tileRect.width) * 100).toFixed(1)}%`);
      tile.style.setProperty("--ly", `${(((light.y - (cy - halfH)) / tileRect.height) * 100).toFixed(1)}%`);

      const markW = tileRect.width * 0.62;
      const markH = markW / MARK_ASPECT;
      uniforms.uLight.value.set(light.x * renderScale, light.y * renderScale);
      uniforms.uTileC.value.set(cx * renderScale, cy * renderScale);
      uniforms.uTileH.value.set(halfW * renderScale, halfH * renderScale);
      uniforms.uTileR.value = Math.min(32, halfW * 0.5) * renderScale;
      uniforms.uMarkH.value.set(
        ((markW * ((MARK_TEX_W + MARK_TEX_PAD * 2) / MARK_TEX_W)) / 2) * renderScale,
        ((markH * ((MARK_TEX_H + MARK_TEX_PAD * 2) / MARK_TEX_H)) / 2) * renderScale,
      );
      uniforms.uSpread.value = tileRect.width * 3.2 * renderScale;
      renderer.render(scene, camera);
    };
    raf = requestAnimationFrame(frame);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      window.removeEventListener("pointermove", onPointerMove);
      geometry.dispose();
      material.dispose();
      markTexture.dispose();
      renderer.dispose();
    };
  }, [tileRef]);

  return (
    <>
      {fallback && <div className={fallbackClassName} aria-hidden="true" />}
      <canvas ref={canvasRef} className={className} aria-hidden="true" />
    </>
  );
}

extraFiles.reveal-text.tsx:
import type { CSSProperties } from "react";
import { MARK_INNER_PATH, MARK_OUTER_PATH } from "./rays-shaders";
import styles from "./styles.module.css";

interface RevealWordsProps {
  text: string;
  base: number;
  step?: number;
}

export function RevealWords({ text, base, step = 0.04 }: RevealWordsProps) {
  const words = text.split(" ");
  return (
    <>
      {words.map((word, i) => (
        <span
          key={i}
          className={styles.w}
          style={{ animationDelay: `${(base + i * step).toFixed(2)}s` }}
        >
          {word}
          {i < words.length - 1 ? "\u00A0" : ""}
        </span>
      ))}
    </>
  );
}

export function RevealLetters({ text }: { text: string }) {
  return (
    <>
      {[...text].map((letter, i) => (
        <span key={i} className={styles.hl} style={{ "--i": i } as CSSProperties}>
          {letter === " " ? "\u00A0" : letter}
        </span>
      ))}
    </>
  );
}

export function BrandMark({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 26.6 25" fill="none" aria-hidden="true">
      <path fillRule="evenodd" clipRule="evenodd" d={MARK_OUTER_PATH} fill="currentColor" />
      <path d={MARK_INNER_PATH} fill="currentColor" />
      <circle cx="4.8" cy="4.4" r="1.7" fill="currentColor" />
      <circle cx="21.8" cy="20.6" r="1.7" fill="currentColor" />
    </svg>
  );
}

export function BrandWordmark({ name, className }: { name: string; className?: string }) {
  return (
    <span className={className}>
      <svg viewBox="0 0 26.6 25" width="19" height="18" fill="none" aria-hidden="true">
        <path fillRule="evenodd" clipRule="evenodd" d={MARK_OUTER_PATH} fill="currentColor" />
        <path d={MARK_INNER_PATH} fill="currentColor" />
      </svg>
      <span className={styles.wordmarkText}>{name}</span>
    </span>
  );
}

extraFiles.waitlist-form.tsx:
"use client";

import { useEffect, useRef, useState, type FormEvent } from "react";
import bubbleStyles from "./bubble.module.css";
import { FEEDBACK_POOLS, IDLE_NUDGES, checkEmail } from "./email-feedback";
import { RevealWords } from "./reveal-text";
import styles from "./styles.module.css";

type SubmitStatus = "idle" | "sending" | "done" | "dupe";
type BubbleSide = "left" | "right" | "center";
type BubbleState =
  | { mode: "hidden" }
  | { mode: "text"; text: string; side: BubbleSide; idle?: boolean }
  | { mode: "enter" };

export type WaitlistSubmitResult = "done" | "dupe" | { error: string } | void;

interface WaitlistFormProps {
  placeholder: string;
  caption: string;
  onSubmit?: (email: string) => Promise<WaitlistSubmitResult> | WaitlistSubmitResult;
}

const PLACEHOLDER_BASE_DELAY = 0.9;
const PLACEHOLDER_LETTER_STEP = 0.07;
const sideFor = (value: string): BubbleSide => (value.includes("@") ? "right" : "left");

export function WaitlistForm({ placeholder, caption, onSubmit }: WaitlistFormProps) {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<SubmitStatus>("idle");
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [focused, setFocused] = useState(false);
  const [bubble, setBubble] = useState<BubbleState>({ mode: "hidden" });

  const submittedRef = useRef<Set<string>>(new Set());
  const poolCursor = useRef<Partial<Record<keyof typeof FEEDBACK_POOLS, number>>>({});
  const quipTimer = useRef(0);
  const idleCursor = useRef(-1);
  const inputWrapRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLSpanElement>(null);
  const bubbleMeasureRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    const measure = measureRef.current;
    const wrap = inputWrapRef.current;
    if (!measure || !wrap) return;
    measure.textContent = email;
    const wrapWidth = wrap.offsetWidth;
    const halfText = measure.offsetWidth / 2;
    const endX = Math.max(0, Math.min(wrapWidth / 2 + halfText, wrapWidth - 120));
    const startX = Math.min(wrapWidth, Math.max(wrapWidth / 2 - halfText, 120));
    wrap.style.setProperty("--endx", `${endX.toFixed(0)}px`);
    wrap.style.setProperty("--startx", `${startX.toFixed(0)}px`);
    let hash = 0;
    for (const ch of email) hash = (hash * 31 + ch.charCodeAt(0)) | 0;
    wrap.style.setProperty("--tilt", `${(Math.abs(hash) % 13) - 6}deg`);
  }, [email]);

  useEffect(() => {
    window.clearTimeout(quipTimer.current);
    if (!email.trim()) {
      setBubble({ mode: "hidden" });
      return;
    }
    const timer = window.setTimeout(() => {
      const verdict = checkEmail(email);
      if (verdict.kind === "pool") {
        const messages = FEEDBACK_POOLS[verdict.pool];
        const index = (poolCursor.current[verdict.pool] ?? -1) + 1;
        poolCursor.current[verdict.pool] = index;
        setBubble({ mode: "text", text: messages[index % messages.length], side: sideFor(email) });
      } else if (verdict.kind === "line") {
        setBubble({ mode: "text", text: verdict.text, side: sideFor(email) });
      } else if (verdict.kind === "quip") {
        setBubble({ mode: "text", text: verdict.text, side: "right" });
        quipTimer.current = window.setTimeout(() => setBubble({ mode: "enter" }), 800);
      } else if (verdict.kind === "enter") {
        setBubble({ mode: "enter" });
      } else {
        setBubble({ mode: "hidden" });
      }
    }, 500);
    return () => window.clearTimeout(timer);
  }, [email]);

  useEffect(() => {
    if (bubble.mode !== "text" || IDLE_NUDGES.includes(bubble.text)) return;
    const timer = window.setTimeout(() => {
      const verdict = checkEmail(email);
      if (verdict.kind === "pool" || verdict.kind === "line") {
        idleCursor.current = (idleCursor.current + 1) % IDLE_NUDGES.length;
        setBubble({ mode: "text", text: IDLE_NUDGES[idleCursor.current], side: "center", idle: true });
      }
    }, 2200);
    return () => window.clearTimeout(timer);
  }, [bubble, email]);

  useEffect(() => {
    const measure = bubbleMeasureRef.current;
    const wrap = inputWrapRef.current;
    if (!measure || !wrap) return;
    if (bubble.mode === "text") {
      measure.textContent = bubble.text;
      const width = measure.offsetWidth + 44 + (bubble.idle ? 26 : 0);
      wrap.style.setProperty("--bw", `${width}px`);
    } else {
      wrap.style.removeProperty("--bw");
    }
  }, [bubble]);

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const address = email.trim().toLowerCase();
    if (!address || status === "sending") return;
    const verdict = checkEmail(address);
    if (verdict.kind !== "enter" && verdict.kind !== "quip") {
      if (verdict.kind === "pool") {
        setBubble({ mode: "text", text: FEEDBACK_POOLS[verdict.pool][0], side: sideFor(address) });
      } else if (verdict.kind === "line") {
        setBubble({ mode: "text", text: verdict.text, side: sideFor(address) });
      }
      return;
    }
    setStatus("sending");
    setErrorMessage(null);
    if (onSubmit) {
      const res = await onSubmit(address);
      if (res === "dupe") setStatus("dupe");
      else if (res && typeof res === "object" && "error" in res) {
        setStatus("idle");
        setErrorMessage(res.error);
      } else {
        setStatus("done");
      }
      return;
    }
    if (submittedRef.current.has(address)) {
      setStatus("dupe");
    } else {
      submittedRef.current.add(address);
      setStatus("done");
    }
  };

  const resetForm = () => {
    setEmail("");
    setStatus("idle");
    setErrorMessage(null);
    setBubble({ mode: "hidden" });
  };

  if (status === "done" || status === "dupe") {
    return (
      <div className={styles.formZone}>
        <p className={styles.bigDone}>
          <RevealWords text={status === "done" ? "You're in." : "Already in."} base={0.1} step={0.08} />
        </p>
        <p className={styles.caption}>
          <RevealWords
            text={status === "done" ? "We'll email you when the gates open." : "This email is on the list."}
            base={0.4}
          />
        </p>
        <button type="button" className={styles.another} onClick={resetForm}>
          Join with another email
        </button>
      </div>
    );
  }

  const phCenter = Math.max(1, placeholder.length - 1) / 2;
  const bubbleLeft =
    bubble.mode === "text" && bubble.side === "left"
      ? "var(--startx, 50%)"
      : bubble.mode === "text" && bubble.side === "center"
        ? "50%"
        : "var(--endx, 50%)";

  return (
    <form className={styles.formZone} onSubmit={handleSubmit}>
      <div ref={inputWrapRef} className={styles.inputWrap}>
        <span ref={measureRef} className={styles.measure} aria-hidden="true" />
        <input
          className={styles.emailInput}
          type="email"
          required
          aria-label={placeholder}
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          onFocus={() => setFocused(true)}
          onBlur={(e) => setFocused(e.target.value.length > 0)}
          disabled={status === "sending"}
        />
        <span className={`${styles.ph} ${focused || email ? styles.phOff : ""}`} aria-hidden="true">
          {[...placeholder].map((letter, i) =>
            letter === " " ? (
              <span key={i}>{"\u00A0"}</span>
            ) : (
              <span
                key={i}
                className={styles.phL}
                style={{
                  animationDelay: `${(PLACEHOLDER_BASE_DELAY + Math.abs(i - phCenter) * PLACEHOLDER_LETTER_STEP).toFixed(2)}s`,
                }}
              >
                {letter}
              </span>
            ),
          )}
        </span>
        <span className={styles.line} aria-hidden="true" />
        <div className={bubbleStyles.bubbleWrap} aria-live="polite" style={{ left: bubbleLeft }}>
          {bubble.mode !== "hidden" && (
            <div
              className={`${bubbleStyles.bubble} ${bubble.mode === "enter" ? bubbleStyles.bubbleEnter : ""} ${
                bubble.mode === "text" && bubble.side === "left"
                  ? bubbleStyles.bubbleLeft
                  : bubble.mode === "text" && bubble.side === "center"
                    ? bubbleStyles.bubbleCenter
                    : ""
              }`}
            >
              {bubble.mode === "enter" ? (
                <button
                  type="submit"
                  className={bubbleStyles.enterBtn}
                  aria-label="Join the waitlist"
                  disabled={status === "sending"}
                >
                  &#x21B5;
                </button>
              ) : (
                <span key={bubble.text} className={bubbleStyles.bubbleText}>
                  {bubble.text}
                  {bubble.idle && (
                    <span className={bubbleStyles.dots} aria-hidden="true"><i /><i /><i /></span>
                  )}
                </span>
              )}
            </div>
          )}
        </div>
        <span ref={bubbleMeasureRef} className={bubbleStyles.bubbleMeasure} aria-hidden="true" />
      </div>
      <p className={styles.caption}>
        <RevealWords text={errorMessage ?? caption} base={errorMessage ? 0 : 1.3} step={0.05} />
      </p>
    </form>
  );
}

section/right-rail-navbar.code:
"use client";

import { useEffect, useState } from "react";
import { ACCOUNT_PATH, CART_PATH, CLOSE_PATHS, HAMBURGER_PATHS } from "./icons";
import styles from "./styles.module.css";

/** A locale code from `locales` (default "en" | "fr"). */
export type NavLocale = string;
export interface NavLinkItem { label: string; href: string; external?: boolean; }
export interface NavAccordionGroup { id: string; label: string; links: NavLinkItem[]; }

export interface RightRailNavbarProps {
  brand?: string; brandHref?: string; showBrandMark?: boolean; brandTone?: "default" | "inverted";
  promoTitle?: string; promoDetail?: string; promoTitleFr?: string; promoDetailFr?: string;
  shopHeading?: string; shopHeadingFr?: string; cartCount?: number; accountHref?: string;
  shopLinks?: NavLinkItem[]; mainLinks?: NavLinkItem[]; accordions?: NavAccordionGroup[];
  defaultOpen?: boolean; onOpenCart?: () => void; onToggleLocale?: (nextLocale: NavLocale) => void;
  showCart?: boolean; showLocaleToggle?: boolean;
  /** [primary, secondary] locale codes; the `*Fr` props hold the secondary-locale copy. The toggle shows the
   *  `localeLabels` entry of the locale it switches to; `localeToggleAriaLabels` is indexed by the active locale. */
  locales?: [string, string]; localeLabels?: [string, string]; localeToggleAriaLabels?: [string, string];
  brandHomeLabel?: string; navAriaLabel?: string; menuOpenLabel?: string; menuCloseLabel?: string;
  cartLabel?: string; accountLabel?: string; shopNavLabel?: string; secondaryNavLabel?: string;
}

const DEFAULT_SHOP_LINKS: NavLinkItem[] = [
  { label: "All products", href: "#collections" },
  { label: "All Coffees", href: "#collections" },
  { label: "Gift Card", href: "#gift-card" },
  { label: "Boxes", href: "#boxes" },
  { label: "Cool Stuff", href: "#goods" },
];

const DEFAULT_MAIN_LINKS: NavLinkItem[] = [
  { label: "About Studio", href: "#about" },
  { label: "Subscribe", href: "#subscribe" },
  { label: "Producers", href: "#producers" },
];

const DEFAULT_ACCORDIONS: NavAccordionGroup[] = [
  {
    id: "our-products",
    label: "Our Products",
    links: [
      { label: "Limited Series", href: "#limited" },
      { label: "Bright Series", href: "#bright" },
      { label: "Warm Series", href: "#warm" },
      { label: "Dark Series", href: "#dark" },
      { label: "Pantry", href: "#pantry" },
    ],
  },
  {
    id: "commercial",
    label: "Commercial",
    links: [
      { label: "Equipment and Technical Advice", href: "#equipment" },
      { label: "Wholesale Partnerships", href: "#partners" },
      { label: "Wholesale Account Application", href: "#application" },
      { label: "Wholesale Catalog", href: "#catalog" },
    ],
  },
];

export function RightRailNavbar({
  brand = "MERIDIAN",
  brandHref = "#main",
  showBrandMark = true,
  brandTone = "default",
  promoTitle = "Free Shipping",
  promoDetail = "Local & metro orders 35$+ | Domestic orders 55$+ | Express courier daily",
  promoTitleFr = "Livraison gratuite",
  promoDetailFr = "Commandes locales 35$+ | Nationales 55$+ | Envoi express quotidien",
  shopHeading = "Shop",
  shopHeadingFr = "Boutique",
  cartCount = 0,
  accountHref = "#footer",
  shopLinks = DEFAULT_SHOP_LINKS,
  mainLinks = DEFAULT_MAIN_LINKS,
  accordions = DEFAULT_ACCORDIONS,
  defaultOpen = false,
  onOpenCart,
  onToggleLocale,
  showCart = true, showLocaleToggle = true, locales = ["en", "fr"], localeLabels = ["EN", "FR"],
  localeToggleAriaLabels = ["See content in French", "Voir le contenu en anglais"],
  brandHomeLabel, navAriaLabel = "Primary navigation", menuOpenLabel = "Menu", menuCloseLabel = "Close menu",
  cartLabel = "Open cart", accountLabel = "Account", shopNavLabel = "Shop", secondaryNavLabel = "Secondary navigation",
}: RightRailNavbarProps) {
  const [menuOpen, setMenuOpen] = useState(defaultOpen);
  const [openAccordion, setOpenAccordion] = useState<string | null>(null);
  const [isSecondary, setIsSecondary] = useState(false);

  useEffect(() => {
    if (!menuOpen) return;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") setMenuOpen(false);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => {
      document.body.style.overflow = prevOverflow;
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [menuOpen]);

  const handleLocaleClick = () => {
    setIsSecondary(!isSecondary);
    onToggleLocale?.(locales[isSecondary ? 0 : 1]);
  };

  const handleLinkClick = () => setMenuOpen(false);
  const activeTitle = isSecondary ? promoTitleFr : promoTitle;
  const activeDetail = isSecondary ? promoDetailFr : promoDetail;

  const logoCls = brandTone === "inverted" ? `${styles.stickyLogo} ${styles.brandInverted}` : styles.stickyLogo;
  const tagCls = brandTone === "inverted" ? `${styles.logoTagline} ${styles.brandInverted}` : styles.logoTagline;

  return (
    <div className={styles.sectionRoot}>
      {showBrandMark ? (
        <>
          <a href={brandHref} className={logoCls} aria-label={brandHomeLabel ?? `${brand} Home`}>
            <svg width="40" height="25" viewBox="0 0 40 25" fill="none" aria-hidden="true">
              <rect x="0" y="0" width="40" height="5.5" />
              <rect x="4" y="9.5" width="36" height="5.5" />
              <rect x="10" y="19" width="30" height="5.5" />
            </svg>
          </a>
          <a href={brandHref} className={tagCls} aria-label={brand}>{brand}</a>
        </>
      ) : null}

      <div className={styles.railWrapper}>
        <header className={styles.railHeader} aria-label={navAriaLabel}>
          <div className={styles.menuTriggerWrap}>
            <button
              type="button"
              className={styles.menuBtn}
              aria-label={menuOpen ? menuCloseLabel : menuOpenLabel}
              aria-expanded={menuOpen}
              onClick={() => setMenuOpen((prev) => !prev)}
            >
              <span className={styles.menuGlyphBox}>
                <svg aria-hidden="true" className={menuOpen ? styles.iconClose : styles.iconHamburger} fill="none" viewBox="0 0 34 34">
                  {(menuOpen ? CLOSE_PATHS : HAMBURGER_PATHS).map((d) => (
                    <path key={d} fillRule="evenodd" clipRule="evenodd" d={d} fill="currentColor" />
                  ))}
                </svg>
              </span>
            </button>
          </div>

          <div className={styles.railLines}>
            <p className={styles.railLine}>{activeTitle}</p>
            <p className={styles.railLine}>{activeDetail}</p>
          </div>

          <div className={styles.railIcons}>
            {showCart ? (
              <button type="button" onClick={onOpenCart} className={styles.cartBtn} aria-label={cartLabel}>
                <svg className={styles.railSvg} aria-hidden="true" viewBox="0 0 20 24" fill="none">
                  <path d={CART_PATH} fillRule="evenodd" fill="currentColor" />
                </svg>
                {cartCount > 0 ? <span className={styles.cartBadge}>{cartCount}</span> : null}
              </button>
            ) : null}

            <a href={accountHref} className={styles.accountLink} aria-label={accountLabel}>
              <svg className={styles.railSvg} aria-hidden="true" viewBox="0 0 28 28" fill="none">
                <path d={ACCOUNT_PATH} fillRule="evenodd" fill="currentColor" />
              </svg>
            </a>

            {showLocaleToggle ? (
              <button
                type="button"
                onClick={handleLocaleClick}
                className={styles.langBtn}
                aria-label={localeToggleAriaLabels[isSecondary ? 1 : 0]}
              >
                {localeLabels[isSecondary ? 0 : 1]}
              </button>
            ) : null}
          </div>
        </header>
      </div>

      <div className={`${styles.navDrawer} ${menuOpen ? styles.isOpen : ""}`} aria-hidden={!menuOpen}>
        <div className={styles.backdrop} onClick={() => setMenuOpen(false)} />
        <div className={styles.drawerPanel}>
          <nav className={styles.topNav} aria-label={shopNavLabel}>
            <p className={styles.shopHeading}>{isSecondary ? shopHeadingFr : shopHeading}</p>
            <ul className={styles.menuList} role="list">
              {shopLinks.map((item) => (
                <li key={item.label} className={styles.menuItem}>
                  <a href={item.href} tabIndex={menuOpen ? undefined : -1} onClick={handleLinkClick} className={styles.shopLink}>
                    {item.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          <nav aria-label={secondaryNavLabel}>
            <ul className={styles.menuList} role="list">
              {mainLinks.map((item) => (
                <li key={item.label} className={styles.menuItem}>
                  <a href={item.href} tabIndex={menuOpen ? undefined : -1} onClick={handleLinkClick} className={styles.mainLink}>
                    {item.label}
                  </a>
                </li>
              ))}

              {accordions.map((group) => {
                const isOpen = openAccordion === group.id;
                return (
                  <li key={group.id} className={styles.menuItem}>
                    <button
                      type="button"
                      tabIndex={menuOpen ? undefined : -1}
                      onClick={() => setOpenAccordion(isOpen ? null : group.id)}
                      className={styles.accBtn}
                      aria-expanded={isOpen}
                    >
                      <span className={styles.cta}>{group.label}</span>
                      <span className={styles.accSign} aria-hidden="true">{isOpen ? "\u2212" : "+"}</span>
                    </button>
                    {isOpen ? (
                      <ul className={styles.accList}>
                        {group.links.map((sub) => (
                          <li key={sub.label} className={styles.menuItem}>
                            <a
                              href={sub.href}
                              target={sub.external ? "_blank" : undefined}
                              rel={sub.external ? "noreferrer noopener" : undefined}
                              tabIndex={menuOpen ? undefined : -1}
                              onClick={handleLinkClick}
                              className={styles.accSubLink}
                            >
                              {sub.label}
                            </a>
                          </li>
                        ))}
                      </ul>
                    ) : null}
                  </li>
                );
              })}
            </ul>
          </nav>
        </div>
      </div>
    </div>
  );
}

