extraFiles.deck-motifs.ts:
// Procedural geometric motifs, heraldic shield path, and stylized avatar portraits.

export interface MotifTheme {
  bg: string;
  primary: string;
  secondary: string;
  glow: string;
}

export const rgb = (r: number, g: number, b: number, a = 1) =>
  a < 1 ? `rgba(${r}, ${g}, ${b}, ${a})` : `rgb(${r}, ${g}, ${b})`;

export const MOTIF_THEMES: MotifTheme[] = [
  { bg: rgb(206, 36, 32), primary: rgb(236, 198, 42), secondary: rgb(26, 20, 22), glow: rgb(206, 62, 48, 0.34) },
  { bg: rgb(104, 92, 62), primary: rgb(216, 178, 38), secondary: rgb(74, 66, 46), glow: rgb(196, 162, 52, 0.3) },
  { bg: rgb(194, 152, 186), primary: rgb(98, 86, 62), secondary: rgb(232, 208, 226), glow: rgb(172, 128, 168, 0.3) },
  { bg: rgb(32, 92, 178), primary: rgb(164, 212, 248), secondary: rgb(18, 56, 124), glow: rgb(56, 128, 212, 0.34) },
  { bg: rgb(192, 42, 34), primary: rgb(28, 24, 28), secondary: rgb(236, 178, 62), glow: rgb(188, 64, 52, 0.32) },
];

const AVATAR_TONES = [
  { bg: rgb(214, 176, 146), shirt: rgb(62, 48, 44), hair: rgb(42, 30, 26) },
  { bg: rgb(178, 196, 188), shirt: rgb(48, 66, 64), hair: rgb(54, 42, 36) },
  { bg: rgb(198, 174, 196), shirt: rgb(66, 48, 72), hair: rgb(34, 26, 38) },
  { bg: rgb(206, 192, 164), shirt: rgb(78, 62, 44), hair: rgb(48, 38, 28) },
];

export function drawMotifPattern(
  ctx: CanvasRenderingContext2D,
  idx: number,
  x: number,
  y: number,
  w: number,
  h: number,
) {
  const theme = MOTIF_THEMES[idx % MOTIF_THEMES.length];
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = theme.bg;
  ctx.fillRect(0, 0, w, h);

  const kind = idx % 5;
  if (kind === 0) {
    ctx.fillStyle = theme.primary;
    const cw = w * 0.28;
    const ch = h * 0.2;
    ctx.fillRect(0, 0, cw, ch);
    ctx.fillRect(w - cw, 0, cw, ch);
    ctx.fillRect(0, h - ch, cw, ch);
    ctx.fillRect(w - cw, h - ch, cw, ch);
    ctx.fillRect(w * 0.44, h * 0.14, w * 0.12, h * 0.42);
    ctx.fillRect(w * 0.3, h * 0.22, w * 0.4, h * 0.06);
    ctx.fillRect(w * 0.34, h * 0.34, w * 0.32, h * 0.06);
    ctx.beginPath();
    ctx.moveTo(w * 0.5, h * 0.48);
    ctx.lineTo(w * 0.72, h * 0.64);
    ctx.lineTo(w * 0.5, h * 0.8);
    ctx.lineTo(w * 0.28, h * 0.64);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = theme.bg;
    ctx.beginPath();
    ctx.moveTo(w * 0.5, h * 0.56);
    ctx.lineTo(w * 0.6, h * 0.64);
    ctx.lineTo(w * 0.5, h * 0.72);
    ctx.lineTo(w * 0.4, h * 0.64);
    ctx.closePath();
    ctx.fill();
  } else if (kind === 1) {
    const cellW = w / 4;
    const cellH = h / 7;
    for (let r = 0; r < 7; r++) {
      for (let c = 0; c < 4; c++) {
        ctx.fillStyle = (r + c) % 2 === 0 ? theme.primary : theme.secondary;
        const cx = c * cellW;
        const cy = r * cellH;
        ctx.beginPath();
        ctx.arc(cx + cellW * 0.5, cy + cellH * 0.52, cellW * 0.52, Math.PI, 0);
        ctx.lineTo(cx + cellW, cy + cellH + 1);
        ctx.lineTo(cx, cy + cellH + 1);
        ctx.closePath();
        ctx.fill();
      }
    }
  } else if (kind === 2) {
    ctx.fillStyle = theme.primary;
    ctx.fillRect(0, h * 0.72, w, h * 0.28);
    ctx.fillRect(w * 0.44, h * 0.42, w * 0.12, h * 0.34);
    const blobs: Array<[number, number, number]> = [
      [0.5, 0.22, 0.13], [0.33, 0.31, 0.12], [0.67, 0.31, 0.12],
      [0.32, 0.47, 0.11], [0.68, 0.47, 0.11], [0.5, 0.39, 0.14],
    ];
    for (const [bx, by, br] of blobs) {
      ctx.beginPath();
      ctx.arc(w * bx, h * by, w * br, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.fillStyle = theme.bg;
    ctx.beginPath();
    ctx.arc(w * 0.5, h * 0.39, w * 0.06, 0, Math.PI * 2);
    ctx.fill();
    for (let i = 0; i < 3; i++) {
      ctx.beginPath();
      ctx.arc(w * (0.2 + i * 0.3), h * 0.86, w * 0.065, 0, Math.PI * 2);
      ctx.fill();
    }
  } else if (kind === 3) {
    const step = h / 8;
    for (let b = 0; b < 8; b++) {
      ctx.fillStyle = b % 2 === 0 ? theme.primary : theme.secondary;
      ctx.beginPath();
      const baseY = b * step;
      ctx.moveTo(0, baseY);
      for (let px = 0; px <= w; px += w / 16) {
        const wave = Math.sin((px / w) * Math.PI * 4 + b * 0.8) * (step * 0.32);
        ctx.lineTo(px, baseY + wave);
      }
      ctx.lineTo(w, h);
      ctx.lineTo(0, h);
      ctx.closePath();
      ctx.fill();
    }
  } else {
    const cw = w / 4;
    const ch = h / 6;
    ctx.fillStyle = theme.primary;
    for (let r = 0; r < 6; r++) {
      for (let c = 0; c < 4; c++) {
        const cx = (c + 0.5) * cw;
        const cy = (r + 0.5) * ch;
        ctx.beginPath();
        ctx.moveTo(cx, cy - ch * 0.44);
        ctx.lineTo(cx + cw * 0.44, cy);
        ctx.lineTo(cx, cy + ch * 0.44);
        ctx.lineTo(cx - cw * 0.44, cy);
        ctx.closePath();
        ctx.fill();
      }
    }
  }
  ctx.restore();
}

export function shieldPath(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number) {
  const r = w * 0.16;
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + w - r, y);
  ctx.arcTo(x + w, y, x + w, y + r, r);
  ctx.lineTo(x + w, y + h * 0.5);
  ctx.quadraticCurveTo(x + w, y + h * 0.86, x + w / 2, y + h);
  ctx.quadraticCurveTo(x, y + h * 0.86, x, y + h * 0.5);
  ctx.lineTo(x, y + r);
  ctx.arcTo(x, y, x + r, y, r);
  ctx.closePath();
}

export function drawAvatarDot(ctx: CanvasRenderingContext2D, cx: number, cy: number, radius: number, seed: number) {
  const tone = AVATAR_TONES[seed % AVATAR_TONES.length];
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, Math.PI * 2);
  ctx.clip();
  ctx.fillStyle = tone.bg;
  ctx.fillRect(cx - radius, cy - radius, radius * 2, radius * 2);
  ctx.fillStyle = tone.shirt;
  ctx.beginPath();
  ctx.arc(cx, cy + radius * 0.95, radius * 0.78, Math.PI, 0);
  ctx.fill();
  ctx.fillStyle = tone.hair;
  ctx.beginPath();
  ctx.arc(cx, cy - radius * 0.14, radius * 0.36, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

extraFiles.deck-scene.ts:
// Three.js WebGL 3D spiral card deck controller with clean disposal and reduced-motion support.

import {
  DoubleSide,
  Group,
  Mesh,
  PerspectiveCamera,
  PlaneGeometry,
  Scene,
  ShaderMaterial,
  Vector2,
  WebGLRenderer,
} from "three";
import { HERO_SPIRAL_CONFIG, type DeckConfig } from "./deck-data";
import { CARD_FRAGMENT_SHADER, CARD_VERTEX_SHADER } from "./deck-shaders";
import { buildCardTexturePair, PLANE_HEIGHT, PLANE_WIDTH, type SpiralCardItem } from "./deck-textures";

const CARD_COUNT = 18;
const CENTER_SLOT = 9;
const CAMERA_Z_OFFSET = 6.5;
const REVEAL_DURATION = 2.2;

export interface SpiralDeckController {
  setPointer: (nx: number, ny: number) => void;
  dragBy: (delta: number) => void;
  dispose: () => void;
}

type CardMesh = Mesh<PlaneGeometry, ShaderMaterial>;

const wrapIndex = (index: number, count: number) => ((index % count) + count) % count;

export function mountSpiralDeck(
  canvas: HTMLCanvasElement,
  cards: SpiralCardItem[],
  footerNote: string,
  reducedMotion: boolean,
  config: Partial<DeckConfig> = {},
): SpiralDeckController | null {
  if (cards.length === 0) return null;
  const cfg: DeckConfig = { ...HERO_SPIRAL_CONFIG, ...config };

  let renderer: WebGLRenderer;
  try {
    renderer = new WebGLRenderer({ canvas, antialias: true, alpha: true });
  } catch {
    return null;
  }

  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setClearColor(0, 0);

  const scene = new Scene();
  const camera = new PerspectiveCamera(38, 1, 0.1, 100);
  camera.position.z = cfg.radius * cfg.squish + CAMERA_Z_OFFSET;

  const textureScale = window.innerWidth <= 768 ? 1.5 : 2;
  const maxAniso = renderer.capabilities.getMaxAnisotropy();
  const { fronts, backs } = buildCardTexturePair(cards, footerNote, textureScale, maxAniso);

  const deckGroup = new Group();
  scene.add(deckGroup);
  const geometry = new PlaneGeometry(PLANE_WIDTH, PLANE_HEIGHT, 24, 16);
  const meshes: CardMesh[] = Array.from({ length: CARD_COUNT }, () => {
    const mat = new ShaderMaterial({
      uniforms: {
        uTex: { value: fronts[0] },
        uBack: { value: backs[0] },
        uBend: { value: cfg.bend },
        uSmear: { value: 0 },
        uDir: { value: new Vector2(0, 1) },
        uDim: { value: 1 },
        uFlip: { value: 0 },
        uCardH: { value: PLANE_HEIGHT },
      },
      vertexShader: CARD_VERTEX_SHADER,
      fragmentShader: CARD_FRAGMENT_SHADER,
      transparent: true,
      side: DoubleSide,
      depthTest: false,
      depthWrite: false,
    });
    const mesh = new Mesh(geometry, mat);
    deckGroup.add(mesh);
    return mesh;
  });

  let alive = true;
  let rafId = 0;
  let spinTarget = 0;
  let spinSmooth = 0;
  let prevPos = 0;
  let velocity = 0;
  let tiltX = 0;
  let tiltZ = 0;
  let pointerX = 0;
  let pointerY = 0;
  let lastPointerX = 0;
  let lastPointerY = 0;
  let lastTime = performance.now() / 1000;
  let lastMoveTime = lastTime;
  let lastFrameTime = 0;
  let renderUntil = lastTime + 1;
  let revealing = !reducedMotion;
  const revealStart = lastTime;

  const positionCards = (now: number, dt: number) => {
    let revealEase = 1;
    if (revealing) {
      const k = Math.min(1, (now - revealStart) / REVEAL_DURATION);
      revealEase = 1 - (1 - k) ** 3;
      if (k >= 1) revealing = false;
    }

    const radius = 12 + (cfg.radius - 12) * revealEase;
    const speed = 1 + (cfg.autoSpeed - 1) * revealEase;
    const baseScale = 0.4 + (cfg.cardScale - 0.4) * revealEase;
    if (cfg.auto && !reducedMotion) spinTarget += speed * dt;

    spinSmooth += (spinTarget - spinSmooth) * Math.min(1, dt * 8);
    if (Math.abs(spinTarget - spinSmooth) < 3e-4) spinSmooth = spinTarget;

    const pos = spinSmooth;
    velocity += ((pos - prevPos) / dt - velocity) * 0.25;
    prevPos = pos;
    const smear = reducedMotion ? 0 : Math.min(0.055, Math.abs(velocity) * 0.012 * cfg.smear);

    const depth = radius * cfg.squish;
    camera.position.z = depth + CAMERA_Z_OFFSET;
    tiltX = reducedMotion ? 0 : tiltX + (-pointerY * cfg.mouseTilt - tiltX) * Math.min(1, dt * 4);
    tiltZ = reducedMotion ? 0 : tiltZ + (pointerX * cfg.mouseTilt - tiltZ) * Math.min(1, dt * 4);
    deckGroup.rotation.x = tiltX;
    deckGroup.rotation.z = -tiltZ;

    const halfH = Math.tan((38 * Math.PI) / 360) * camera.position.z;
    const halfW = halfH * camera.aspect;
    const ptrWX = pointerX * halfW;
    const ptrWY = pointerY * halfH;
    const firstIndex = Math.round(pos) - CENTER_SLOT;

    for (let slot = 0; slot < CARD_COUNT; slot++) {
      const cardIndex = firstIndex + slot;
      const rel = cardIndex - pos;
      const ang = rel * cfg.angleStep;
      const cos = Math.cos(ang);
      const sin = Math.sin(ang);

      let px = radius * sin + rel * cfg.gapX;
      let py = rel * cfg.gapY;
      if (!reducedMotion) {
        const mdx = ptrWX - px;
        const mdy = ptrWY - py;
        const pull = cfg.magnet * Math.exp(-(mdx * mdx + mdy * mdy) / 9);
        px += mdx * pull;
        py += mdy * pull;
      }

      const pz = depth * cos;
      const mesh = meshes[slot];
      mesh.position.set(px, py, pz);
      mesh.rotation.set(0, ang, -sin * cfg.edgeTwist);
      mesh.scale.setScalar(baseScale);
      mesh.renderOrder = Math.round(pz * 100);

      const texIdx = wrapIndex(cardIndex, cards.length);
      const u = mesh.material.uniforms;
      u.uTex.value = fronts[texIdx];
      u.uBack.value = backs[texIdx];
      u.uBend.value = cfg.bend;
      u.uSmear.value = smear;
      u.uDim.value = Math.max(0.32, 0.5 + 0.5 * cos);
    }
  };

  const resize = () => {
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    if (w <= 0 || h <= 0) return;
    renderer.setSize(w, h, false);
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    const now = performance.now() / 1000;
    positionCards(now, 0.016);
    renderer.render(scene, camera);
    renderUntil = now + 0.45;
  };

  resize();
  const observer = new ResizeObserver(resize);
  observer.observe(canvas);
  window.addEventListener("resize", resize);

  const frame = () => {
    if (!alive) return;
    const now = performance.now() / 1000;
    const moved =
      Math.abs(pointerX - lastPointerX) > 1e-4 ||
      Math.abs(pointerY - lastPointerY) > 1e-4 ||
      revealing;
    if (moved) lastMoveTime = now;

    if (now - lastMoveTime > 2 && now - lastFrameTime < 1 / 30) {
      rafId = requestAnimationFrame(frame);
      return;
    }
    lastFrameTime = now;
    const dt = Math.min(0.05, now - lastTime) || 0.016;
    lastTime = now;

    positionCards(now, dt);
    const active = moved || Math.abs(spinTarget - spinSmooth) > 3e-4;
    lastPointerX = pointerX;
    lastPointerY = pointerY;
    if ((cfg.auto && !reducedMotion) || active) renderUntil = now + 0.45;
    if (now <= renderUntil) renderer.render(scene, camera);
    if (!reducedMotion) rafId = requestAnimationFrame(frame);
  };

  if (!reducedMotion) rafId = requestAnimationFrame(frame);

  return {
    setPointer(nx, ny) {
      pointerX = nx;
      pointerY = ny;
      renderUntil = performance.now() / 1000 + 0.45;
    },
    dragBy(delta) {
      spinTarget += delta;
      const now = performance.now() / 1000;
      renderUntil = now + 0.45;
      if (reducedMotion) {
        positionCards(now, 0.016);
        renderer.render(scene, camera);
      }
    },
    dispose() {
      alive = false;
      cancelAnimationFrame(rafId);
      observer.disconnect();
      window.removeEventListener("resize", resize);
      geometry.dispose();
      meshes.forEach((m) => m.material.dispose());
      fronts.forEach((t) => t.dispose());
      backs.forEach((t) => t.dispose());
      renderer.dispose();
    },
  };
}

extraFiles.deck-shaders.ts:
// GLSL shaders for curved 3D deck cards: vertex curl/flip and fragment smear/back.

export const CARD_VERTEX_SHADER = `
uniform float uBend;
uniform float uFlip;
uniform float uCardH;
varying vec2 vUv;

void main() {
  vUv = uv;
  vec3 p = position;
  p.z -= uBend * position.x * position.x;
  p.z -= uBend * 0.35 * position.y * position.y;
  if (uFlip > 0.0001) {
    float yN = position.y / uCardH + 0.5;
    float delay = 0.2;
    float rp = clamp((uFlip - (1.0 - yN) * delay) / (1.0 - delay), 0.0, 1.0);
    float a = rp * 6.2831853;
    float s = sin(a), c = cos(a);
    float nx = p.x * c - p.z * s;
    p.z = p.x * s + p.z * c;
    p.x = nx;
  }
  gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
}
`;

export const CARD_FRAGMENT_SHADER = `
precision highp float;
uniform sampler2D uTex;
uniform sampler2D uBack;
uniform float uSmear;
uniform vec2 uDir;
uniform float uDim;
varying vec2 vUv;

void main() {
  if (!gl_FrontFacing) {
    vec4 b = texture2D(uBack, vUv);
    gl_FragColor = vec4(b.rgb * max(uDim, 0.7), b.a);
    return;
  }
  if (uSmear < 0.0008) {
    vec4 c0 = texture2D(uTex, vUv);
    c0.rgb *= uDim;
    gl_FragColor = c0;
    return;
  }
  vec4 acc = vec4(0.0);
  float total = 0.0;
  for (int i = 0; i < 7; i++) {
    float t = float(i) / 6.0 - 0.5;
    float w = 1.0 - abs(t) * 1.3;
    if (w <= 0.0) continue;
    acc += texture2D(uTex, vUv + uDir * t * uSmear) * w;
    total += w;
  }
  vec4 c = acc / total;
  c.rgb *= uDim;
  gl_FragColor = c;
}
`;

extraFiles.deck-textures.ts:
// Procedural Canvas2D front and back card texture builder (zero external assets).

import { CanvasTexture, LinearMipmapLinearFilter, NoColorSpace } from "three";
import { drawAvatarDot, drawMotifPattern, MOTIF_THEMES, rgb, shieldPath } from "./deck-motifs";

export interface SpiralCardItem {
  id: number;
  house: string;
  title: string;
  body: string;
  duration?: string;
  extraCount?: number;
  patternIndex?: number;
}

export const CARD_WIDTH = 345;
export const CARD_HEIGHT = 490;
export const PLANE_WIDTH = 2.4;
export const PLANE_HEIGHT = (CARD_HEIGHT / CARD_WIDTH) * PLANE_WIDTH;
export const CARD_FONT = "-apple-system, system-ui, 'DM Sans', 'Helvetica Neue', sans-serif";
export const DEFAULT_FOOTER_NOTE = "In-person beats text for anything that matters.";

function wrapText(
  ctx: CanvasRenderingContext2D,
  text: string,
  x: number,
  y: number,
  maxWidth: number,
  lineHeight: number,
  maxLines = 99,
): number {
  let line = "";
  let lines = 0;
  const emit = (str: string) => {
    ctx.fillText(str, x, y);
    y += lineHeight;
    lines++;
  };
  for (let word of text.split(" ")) {
    const candidate = line ? `${line} ${word}` : word;
    if (ctx.measureText(candidate).width <= maxWidth) {
      line = candidate;
      continue;
    }
    if (line && (emit(line), (line = ""), lines >= maxLines)) return y;
    while (ctx.measureText(word).width > maxWidth) {
      let cut = 1;
      while (cut < word.length && ctx.measureText(word.slice(0, cut + 1)).width <= maxWidth) cut++;
      emit(word.slice(0, cut));
      if (lines >= maxLines) return y;
      word = word.slice(cut);
    }
    line = word;
  }
  if (line && lines < maxLines) emit(line);
  return y;
}

export function paintCardBack(canvas: HTMLCanvasElement, patternIdx: number, scale: number) {
  canvas.width = CARD_WIDTH * scale;
  canvas.height = CARD_HEIGHT * scale;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  ctx.setTransform(scale, 0, 0, scale, 0, 0);
  ctx.clearRect(0, 0, CARD_WIDTH, CARD_HEIGHT);
  ctx.save();
  ctx.beginPath();
  ctx.roundRect(0, 0, CARD_WIDTH, CARD_HEIGHT, 20);
  ctx.clip();
  drawMotifPattern(ctx, patternIdx, 0, 0, CARD_WIDTH, CARD_HEIGHT);
  ctx.restore();
}

export function paintCardFront(
  canvas: HTMLCanvasElement,
  card: SpiralCardItem,
  footerNote: string,
  scale: number,
) {
  canvas.width = CARD_WIDTH * scale;
  canvas.height = CARD_HEIGHT * scale;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const patternIdx = card.patternIndex ?? (card.id % MOTIF_THEMES.length);
  const theme = MOTIF_THEMES[patternIdx % MOTIF_THEMES.length];

  ctx.setTransform(scale, 0, 0, scale, 0, 0);
  ctx.clearRect(0, 0, CARD_WIDTH, CARD_HEIGHT);
  ctx.beginPath();
  ctx.roundRect(0, 0, CARD_WIDTH, CARD_HEIGHT, 20);
  ctx.fillStyle = rgb(239, 239, 239);
  ctx.fill();

  const shieldW = 56;
  const shieldH = shieldW * 1.12;
  ctx.save();
  shieldPath(ctx, 16, 24, shieldW, shieldH);
  ctx.shadowColor = theme.glow;
  ctx.shadowBlur = 18;
  ctx.shadowOffsetY = 4;
  ctx.fillStyle = rgb(220, 220, 220);
  ctx.fill();
  ctx.restore();

  ctx.save();
  shieldPath(ctx, 16, 24, shieldW, shieldH);
  ctx.clip();
  drawMotifPattern(ctx, patternIdx, 16, 24, shieldW, shieldH);
  ctx.restore();

  ctx.save();
  ctx.beginPath();
  ctx.roundRect(0, 0, CARD_WIDTH, CARD_HEIGHT, 20);
  ctx.clip();
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";

  let y = 106.72;
  ctx.font = `400 16px ${CARD_FONT}`;
  ctx.fillStyle = rgb(131, 131, 131);
  ctx.fillText(card.house, 16, y);

  ctx.font = `700 33px ${CARD_FONT}`;
  ctx.fillStyle = rgb(12, 12, 14);
  y = wrapText(ctx, card.title, 16, y + 36, CARD_WIDTH - 32, 33 * 0.97, 5);

  ctx.font = `400 16px ${CARD_FONT}`;
  ctx.fillStyle = rgb(70, 70, 70);
  wrapText(ctx, card.body, 16, y + 14, CARD_WIDTH - 32, 16 * 1.24, 4);

  const pillsY = CARD_HEIGHT - 87;
  const durationLabel = card.duration ?? "0:18";
  const moreLabel = `+${card.extraCount ?? 12}`;
  ctx.font = `500 14px ${CARD_FONT}`;
  ctx.textBaseline = "middle";
  let cursor = 16;
  for (let i = 0; i < 3; i++) {
    const pillW = 40 + ctx.measureText(durationLabel).width + 8;
    ctx.beginPath();
    ctx.roundRect(cursor, pillsY, pillW, 40, 20);
    ctx.fillStyle = rgb(255, 255, 255, 0.78);
    ctx.fill();
    drawAvatarDot(ctx, cursor + 20, pillsY + 20, 16, card.id + i);
    ctx.fillStyle = rgb(131, 131, 131);
    ctx.fillText(durationLabel, cursor + 40, pillsY + 21);
    cursor += pillW + 4;
  }
  const moreW = 16 + ctx.measureText(moreLabel).width;
  ctx.beginPath();
  ctx.roundRect(cursor, pillsY, moreW, 40, 20);
  ctx.fillStyle = rgb(255, 255, 255, 0.78);
  ctx.fill();
  ctx.fillStyle = rgb(131, 131, 131);
  ctx.fillText(moreLabel, cursor + 8, pillsY + 21);
  ctx.textBaseline = "alphabetic";

  ctx.fillStyle = rgb(242, 242, 242);
  ctx.fillRect(0, CARD_HEIGHT - 38, CARD_WIDTH, 38);
  ctx.strokeStyle = rgb(0, 0, 0, 0.08);
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(0, CARD_HEIGHT - 38);
  ctx.lineTo(CARD_WIDTH, CARD_HEIGHT - 38);
  ctx.stroke();

  ctx.font = `400 12px ${CARD_FONT}`;
  ctx.fillStyle = rgb(131, 131, 131);
  ctx.textAlign = "center";
  wrapText(ctx, footerNote, CARD_WIDTH / 2, CARD_HEIGHT - 22, CARD_WIDTH - 36, 14, 2);
  ctx.restore();
}

export function buildCardTexturePair(
  cards: SpiralCardItem[],
  footerNote: string,
  scale: number,
  maxAnisotropy: number,
): { fronts: CanvasTexture[]; backs: CanvasTexture[] } {
  const fronts: CanvasTexture[] = [];
  const backs: CanvasTexture[] = [];
  for (let i = 0; i < cards.length; i++) {
    const frontCanvas = document.createElement("canvas");
    const backCanvas = document.createElement("canvas");
    paintCardFront(frontCanvas, cards[i], footerNote, scale);
    paintCardBack(backCanvas, cards[i].patternIndex ?? i, scale);

    const frontTex = new CanvasTexture(frontCanvas);
    frontTex.colorSpace = NoColorSpace;
    frontTex.anisotropy = Math.min(8, maxAnisotropy);
    frontTex.minFilter = LinearMipmapLinearFilter;

    const backTex = new CanvasTexture(backCanvas);
    backTex.colorSpace = NoColorSpace;
    backTex.anisotropy = Math.min(8, maxAnisotropy);

    fronts.push(frontTex);
    backs.push(backTex);
  }
  return { fronts, backs };
}

