  display: flex;
  justify-content: center;
  cursor: default;
}

.bigNumber {
  --spot-x: -100%;
  --spot-y: -100%;
  font-family: var(--rk-font-display);
  font-size: 28vw;
  font-weight: 400;
  line-height: 0.85;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
  text-transform: none;
  background: radial-gradient(
    circle 400px at var(--spot-x) var(--spot-y),
    var(--stat-muted),
    var(--stat-ink) 100%
  );
  -webkit-text-fill-color: transparent;
  -webkit-background-clip: text;
  background-clip: text;
}

.divider {
  width: 100%;
  height: 1px;
  margin-top: 48px;
  background: var(--stat-ink);
  opacity: 0.12;
  transform-origin: 0;
}

.textRow {
  display: grid;
  grid-template-columns: 1fr 2fr 2fr;
  gap: 40px;
  margin-top: 32px;
}

.colText {
  margin: 0;
  color: var(--stat-muted);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.7;
  /* Substitute-font compensation: DM Sans sets the original's copy ~3.7% wider
     than Switzer (820 vs 788px, 1324 vs 1277px at 14px), i.e. ~0.017em per glyph. */
  letter-spacing: -0.017em;
}

.colText:first-child {
  color: var(--stat-ink);
  font-weight: 500;
}

@media (max-width: 768px) {
  .section {
    padding: 80px 20px 60px;
  }

  .bigNumber {
    font-size: 42vw;
  }

  .divider {
    margin-top: 32px;
  }

  .textRow {
    grid-template-columns: 1fr;
    gap: 18px;
    margin-top: 24px;
  }

  .colText {
    font-size: 13px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .divider {
    opacity: 0.12;
    transform: none;
  }
}

