}

.crest img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.55s, transform 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.sub {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  max-width: 471px;
