  padding-top: 17px;
}

.row::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: color-mix(in srgb, var(--rk-bg) 10%, transparent);
  transform: scaleX(var(--rp, 0));
  transform-origin: 50%;
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.itemLeft {
  width: 100%;
  max-width: 331px;
  display: flex;
  flex-direction: column;
  transform: translateX(calc((1 - var(--rp, 0)) * 17vw));
  opacity: var(--rp, 0);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.65s ease;
}

.itemLabel {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  margin: 0;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.24;
}

.itemTitle {
  color: var(--rk-bg);
  margin: 3px 0 0;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.12;
}

.itemNum {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  margin: auto 0 17px;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.3125;
}

.itemPhoto {
  display: block;
  object-fit: cover;
  align-self: start;
  width: clamp(170px, 14vw, 201px);
  height: clamp(112px, 9.2vw, 133px);
  clip-path: inset(calc((1 - var(--rp, 0)) * 50%));
  transition: clip-path 0.65s cubic-bezier(0.22, 1, 0.36, 1);
}

.itemDesc {
  color: color-mix(in srgb, var(--rk-bg) 60%, transparent);
  width: 100%;
  max-width: 335px;
  justify-self: end;
  margin: 0;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.24;
  transform: translateX(calc((1 - var(--rp, 0)) * -17vw));
  opacity: var(--rp, 0);
  transition: transform 0.65s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.65s ease;
}

@media (max-width: 768px) {
  .colontitle { top: max(25px, env(safe-area-inset-top)); left: 16px; right: 16px; }
  .inner { padding: 46px 16px 12vh; }
  .head { font-size: clamp(33px, 10.2vw, 40px); }
  .sub { display: none; }
  .list { margin-top: 34px; }
  .row {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 9px;
    min-height: 0;
    margin-bottom: 13px;
    padding-top: 14px;
  }
  .row::before { transform: none; }
  .itemLeft {
    opacity: 1;
    flex-direction: row;
    justify-content: space-between;
    align-items: flex-end;
    gap: 14px;
    width: 100%;
    max-width: none;
    transform: none;
  }
  .itemLeft > div { flex: auto; min-width: 0; }
  .itemNum { white-space: nowrap; margin: 0; }
  .itemPhoto {
    aspect-ratio: 153 / 101;
    clip-path: none;
    align-self: flex-start;
    width: min(153px, 42vw);
    height: auto;
  }
  .itemDesc { opacity: 1; place-self: stretch start; width: 100%; max-width: none; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .headLine { opacity: 1; transform: none; animation: none; }
  .row::before,
  .itemLeft,
  .itemPhoto,
  .itemDesc,
  .crest img {
    opacity: 1;
    transform: none;
    clip-path: none;
    transition: none;
  }
}

